window.SIGA_QUESTION_BANKS={"employee":[{"id":1,"mode":"binary","text":"تستعد جهة عملك لتشغيل نظام جديد، وعُرض عليك الانضمام إلى فريق واحد فقط؛ فأيهما تفضل؟","options":[{"text":"فريق يختبر دقة مخرجات النظام، ويحلل العلاقة بين مدخلاته ونتائجه، ويكتشف جوانب الخلل فيه.","code":"المقاتل المنفرد"},{"text":"فريق يضع خطوات تشغيل النظام، ويحدد مسؤوليات مستخدميه، وينظم آلية تطبيقه ومتابعته.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":2,"mode":"binary","text":"إذا عُرض عليّ العمل في بيئتين متقاربتين في المزايا؛ إحداهما تتغير فيها المهام والمشروعات باستمرار، والأخرى مستقرة وتتكرر فيها طبيعة الأعمال بصورة واضحة، فإنني غالبًا:","options":[{"text":"أختار البيئة المتغيرة؛ لأنها تمنحني باستمرار تجارب جديدة وفرصًا للتعلم والتطور.","code":"(I التأثير)"},{"text":"أختار البيئة المستقرة، وأفضّل أن تكون المهام واضحة ومتوقعة بدل الانتقال المستمر بين أعمال وتجارب جديدة.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":3,"mode":"binary","text":"عند استلام قيادة فريق جديد، فإن أول ما أركز عليه غالبًا هو:","options":[{"text":"وضع اتجاه واضح للعمل، وتحديد مسؤوليات كل عضو في الفريق.","code":"(D الهيمنة)"},{"text":"بناء علاقة إيجابية مع الفريق، وتحفيزهم للعمل بروح واحدة.","code":"(I التأثير)"}],"meta":{"indicator":"ديسك"}},{"id":4,"mode":"binary","text":"إذا طُلب منك قيادة مشروع جديد يشارك فيه عدد من الأشخاص، فأي الطريقتين تفضل؟","options":[{"text":"أضع الخطة، وأقود المشروع من خلال مشاركتي المباشرة في تنفيذ أعماله الأساسية حتى ينطلق كما أريد.","code":"المقاتل المنفرد"},{"text":"أجتمع بالفريق، وأشركهم في وضع الخطة ، وأحفزهم على تنفيذها معًا.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":5,"mode":"binary","text":"عندما أؤدي مهمة في العمل أو الدراسة بطريقة معتادة تحقق نتائج جيدة، ثم أتعرف على طريقة جديدة قد تكون أسرع أو أفضل، لكنها لم تُجرَّب بما يكفي، فأنا أقرب إلى:","options":[{"text":"تجربة الطريقة الجديدة؛ لأنها قد تحسن النتيجة أو تختصر الوقت، حتى لو لم تكن نتائجها مضمونة بعد.","code":"(C الدقة)"},{"text":"الاستمرار بالطريقة التي أثبتت نجاحها، وعدم الاعتماد على الطريقة الجديدة حتى تتضح نتائجها بشكل أكبر.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":6,"mode":"binary","text":"حدث خلاف بين شخصين في جهة عملك، وعُرض عليك تولي دور واحد فقط في معالجته؛ فأيهما تفضل؟","options":[{"text":"جمع الوقائع من الطرفين، وترتيب الأحداث، والتحقق من اتساق أقوالهما؛ لتكوين صورة موضوعية عما حدث.","code":"(D الهيمنة)"},{"text":"الاستماع إلى الطرفين، وفهم مشاعرهما واحتياجاتهما، ومساعدتهما على استعادة الحوار والتفاهم.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":7,"mode":"binary","text":"إذا واجه الفريق صعوبة في إنجاز مهمة في غاية الأهمية، فإن أول ما أركز عليه غالبًا هو:","options":[{"text":"أتولى قيادة الموقف، وأحدد الأولويات، وأوجه الفريق حتى تتحقق النتائج.","code":"(D الهيمنة)"},{"text":"أحافظ على هدوء الفريق، وأساعدهم على التقدم بخطوات ثابتة حتى يكتمل العمل.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":8,"mode":"binary","text":"عندما أبحث في قضية مهمة وأصل إلى رأي يختلف بوضوح عن الرأي المتعارف عليه في أسرتي أو مجتمعي، فإنني غالبًا:","options":[{"text":"أتمسك بالرأي الذي توصلت إليه واقتنعت به، حتى لو خالف ما يراه معظم من حولي.","code":"(I التأثير)"},{"text":"أراعي القيم والعادات المستقرة في أسرتي أو مجتمعي، وأميل إلى عدم مخالفتها حتى لو كان رأيي الشخصي مختلفًا عنها.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":9,"mode":"binary","text":"عُرض عليك موضوع جديد، وطُلب منك إعداد معالجة واحدة له؛ فأيهما تفضل؟","options":[{"text":"إعداد تحليل يفكك عناصر الموضوع، ويفحص تفاصيله، ويوضح العلاقات بين أسبابه ونتائجه.","code":"(A التحليلي)"},{"text":"إعداد تصور شامل يربط الموضوع بمجالات مختلفة، ويستكشف الإمكانات التي يمكن أن تتطور منه.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":10,"mode":"binary","text":"إذا واجه الفريق اعتراضًا على قرار اتخذته، فإنني أميل إلى:","options":[{"text":"التمسك بالقرار بعد توضيح مبرراته، وتوجيه الفريق إلى البدء في تنفيذه لتحقيق النتائج.","code":"(D الهيمنة)"},{"text":"مراجعة أسباب الاعتراض، وتحليل أثر القرار قبل تثبيت مسار التنفيذ.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":11,"mode":"binary","text":"في يوم إجازتي، إذا كان لدي عمل شخصي يمكن تأجيله دون أن يترتب على ذلك ضرر، وفي الوقت نفسه تتاح لي فرصة لنشاط أستمتع به، فإنني غالبًا:","options":[{"text":"أستفيد من وقت الإجازة وأشارك في النشاط، وأؤجل العمل إلى وقت آخر مناسب.","code":"(S الثبات)"},{"text":"أفضّل إنجاز العمل في الوقت الذي خططت له، حتى لو فاتتني فرصة النشاط هذه المرة.","code":"(D الهيمنة)"}],"meta":{"indicator":"ديسك"}},{"id":12,"mode":"binary","text":"في مشروع جماعي، طُلب منك تولي مسؤولية واحدة فقط، بينما يتولى زميلك المسؤولية الأخرى؛ فأيهما تفضل؟","options":[{"text":"توزيع المهام، وتحديد المواعيد، ومتابعة تقدم العمل حتى يكتمل وفق الخطة.","code":"(C الدقة)"},{"text":"إشراك أعضاء الفريق، وتعزيز التعاون بينهم، ومعالجة ما قد يؤثر في تفاهمهم وانسجامهم.","code":"(I التأثير)"}],"meta":{"indicator":"ديسك"}},{"id":13,"mode":"binary","text":"عند اكتشاف خطأ أثناء تنفيذ العمل، فإن الخيار الأقرب لطريقتي والذي أرتاح إليه غالبًا هو:","options":[{"text":"اتخاذ إجراء فوري لمعالجة الخطأ وضمان استمرار العمل.","code":"(D الهيمنة)"},{"text":"تحليل سبب الخطأ، والتأكد من عدم تكراره قبل متابعة العمل.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":14,"mode":"binary","text":"بعد أن أضع خطة واضحة لإنجاز مشروع، ثم تظهر أثناء التنفيذ ظروف جديدة تجعل بعض الخطوات أقل ملاءمة، فإنني غالبًا:","options":[{"text":"أعدّل الخطة وأعيد ترتيب بعض خطواتها بما يتناسب مع الظروف الجديدة، حتى لو ابتعد التنفيذ عن الخطة الأصلية.","code":"(C الدقة)"},{"text":"أحافظ على الخطة الأساسية، ولا أغيّر منها إلا ما تفرضه الظروف؛ حتى يبقى التنفيذ قريبًا من المسار المحدد مسبقًا.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":15,"mode":"binary","text":"إذا استعديت لاختبار مهم، ولم يتبقَّ سوى وقت محدود للمراجعة، فأيهما أقرب إلى طريقتك؟","options":[{"text":"أفضل أن أسير وفق خطة مراجعة أضعها لنفسي حتى أصل إلى أفضل نتيجة.","code":"المقاتل المنفرد"},{"text":"أنظم جلسة مراجعة مع زملائي، وأشجعهم على التعاون حتى نستفيد جميعًا.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":16,"mode":"binary","text":"لديك وقت محدود لتعلّم استخدام برنامج جديد فأي الطريقتين أدناه تفضل؟","options":[{"text":"اتباع دليل تدريبي مرتب، وإتقان خطوات الاستخدام الأساسية بالتسلسل.","code":"(B التنفيذي)"},{"text":"تجربة البرنامج مباشرة، واستكشاف خصائصه وطرق استخدامه بحرية.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":17,"mode":"binary","text":"عند تقديم فكرة جديدة أمام الآخرين، فإن الخيار الأقرب لطريقتي والذي أرتاح إليه غالبًا هو:","options":[{"text":"عرض الفكرة بأسلوب مؤثر يجذب اهتمام الآخرين ويزيد من حماسهم لتأييدها.","code":"(I التأثير)"},{"text":"ترتيب الفكرة بصورة واضحة ومنطقية تساعد الآخرين على فهمها وتطبيقها.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":18,"mode":"binary","text":"إذا استعدت الأسرة لاستقبال مناسبة مهمة تتطلب دقة وتنظيمًا، فأي الأسلوبين تفضل؟","options":[{"text":"أحرص على أن أتولى الأعمال الأكثر حساسية حتى تخرج بالمستوى الذي أطمح إليه.","code":"القناص"},{"text":"أوزع الأعمال، وأوجه أفراد الأسرة، وأتابع تنفيذها حتى تظهر بأفضل صورة.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":19,"mode":"binary","text":"إذا كان أمامي في الوقت نفسه مشروعان متقاربان في الجهد والوقت؛ أحدهما يحقق لي عائدًا ماليًا ومصلحة شخصية أكبر، والآخر يحقق نفعًا مباشرًا لأشخاص يمكنهم الاستفادة منه، فإنني غالبًا:","options":[{"text":"أختار المشروع الذي يحقق لي العائد والمصلحة الشخصية الأكبر.","code":"(D الهيمنة)"},{"text":"أختار المشروع الذي يحقق فائدة وأثرًا أكبر للآخرين.","code":"(I التأثير)"}],"meta":{"indicator":"ديسك"}},{"id":20,"mode":"binary","text":"تكررت مشكلة تؤثر في سير العمل، وشُكّل فريقان لمعالجتها، ويمكنك الانضمام إلى فريق واحد فقط؛ فأيهما تختار؟","options":[{"text":"فريق يتعمق في تحليل المشكلة، ويدرس العوامل المرتبطة بها؛ لتحديد السبب الجذري وراء تكرارها.","code":"(A التحليلي)"},{"text":"فريق يضع إجراءات عملية واضحة، ويوزع مسؤوليات تطبيقها، ويتابع الالتزام بها للحد من تكرار المشكلة.","code":"(B التنفيذي)"}],"meta":{"indicator":"هيرمان"}},{"id":21,"mode":"binary","text":"عندما يحتاج النقاش في الاجتماع إلى توجيه، فإنني أميل أكثر إلى:","options":[{"text":"قيادة النقاش نحو قرار واضح، وتحديد ما يلزم تنفيذه بعد الاجتماع.","code":"(D الهيمنة)"},{"text":"تنشيط الحوار، وتشجيع الحضور على المشاركة وطرح آرائهم بثقة.","code":"(I التأثير)"}],"meta":{"indicator":"ديسك"}},{"id":22,"mode":"binary","text":"إذا طُلب منك تنفيذ مبادرة تطوعية تخدم المجتمع، فأي الأسلوبين تفضل؟","options":[{"text":"أبادر بالعمل ميدانيًا، وأكون في مقدمة المنفذين حتى يتحقق الإنجاز.","code":"المقاتل المنفرد"},{"text":"أستقطب المتطوعين، وأوزع الأدوار، وأحفزهم حتى تنجح المبادرة.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":23,"mode":"binary","text":"عندما أعمل على مهمة مهمة وأصل إلى مستوى جيد، لكنني أرى أن بإمكاني الوصول إلى نتيجة متميزة إذا بذلت جهدًا أكبر، بينما يوجد شخص قريب مني يحتاج إلى وقتي ومساندتي، فإنني غالبًا:","options":[{"text":"أركز على إكمال المهمة بالمستوى المتميز الذي أطمح إليه، ثم أخصص وقتي للمساعدة بعد ذلك.","code":"(S الثبات)"},{"text":"أكتفي بالمستوى الجيد في المهمة، وأخصص جزءًا من وقتي لمساندة الشخص الذي يحتاج إليّ.","code":"(D الهيمنة)"}],"meta":{"indicator":"ديسك"}},{"id":24,"mode":"binary","text":"أرادت جهة عملك تطوير إحدى خدماتها، وعُرض عليك الانضمام إلى فريق واحد فقط؛ فأيهما تختار؟","options":[{"text":"فريق يصنف ملاحظات المستفيدين ويحلل تكرارها والعلاقات بينها؛ لتحديد المشكلات الأكثر تأثيرًا.","code":"قائد التشجيع"},{"text":"فريق يلتقي بالمستفيدين ويستمع إلى تجاربهم واحتياجاتهم؛ لفهم ما يتوقعونه من الخدمة.","code":"المقاتل المنفرد"}],"meta":{"indicator":"الدوافع"}},{"id":25,"mode":"binary","text":"إذا شاركت في منافسة ترفيهية، فأي الخيارين يمنحك متعة أكبر؟","options":[{"text":"أن أعتمد على أدائي الشخصي لتحقيق الفوز.","code":"المقاتل المنفرد"},{"text":"أن أقود الفريق وأحفزه حتى نحقق الفوز معًا.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":26,"mode":"binary","text":"عندما أكون مقتنعًا بفكرة مهمة، ويعارضها أشخاص أحتاج إلى تعاونهم، فإنني غالبًا:","options":[{"text":"أواصل محاولة إقناعهم وتغيير موقفهم حتى أكسب تأييدهم للفكرة.","code":"(D الهيمنة)"},{"text":"أتقبل بقاءهم على رأي مختلف، وأتعامل معهم باحترام دون أن أرى ضرورة لتغيير موقفهم.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":27,"mode":"binary","text":"عند تشكيل فريق لإعداد مشروع جديد، عُرض عليك تولي دور واحد فقط؛ فأيهما تختار؟","options":[{"text":"الفكرة التي يقوم تصورها على منطق متماسك، ويمكن تفسير كيف ستؤدي إلى النتائج المطلوبة.","code":"(A التحليلي)"},{"text":"الفكرة التي تقدم اتجاهًا غير مألوف، وتفتح إمكانات وفرصًا جديدة يمكن تطويرها.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":28,"mode":"binary","text":"عند بدء مشروع شخصي جديد، فأيهما أقرب لطريقتك؟","options":[{"text":"أبدأ بتنفيذ الفكرة بنفسي، وأوسع العمل لاحقًا إذا احتجت إلى ذلك.","code":"المقاتل المنفرد"},{"text":"أبدأ بتكوين فريق متحمس، وأوزع الأدوار منذ البداية حتى ننطلق معًا.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":29,"mode":"binary","text":"إذا أتيحت لي فرصتان متقاربتان في المزايا؛ الأولى تمنحني منصبًا أعلى ومكانة أكبر، والثانية أقل مكانة لكنها تتيح لي خدمة الآخرين بصورة مباشرة وتحقيق أثر واضح، فإنني غالبًا:","options":[{"text":"أختار الفرصة التي تمنحني منصبًا أعلى ومجالًا أكبر للتقدم والمكانة.","code":"(S الثبات)"},{"text":"أختار الفرصة التي أستطيع من خلالها تقديم خدمة أكبر وتحقيق أثر مباشر، حتى لو كان منصبها أقل.","code":"(D الهيمنة)"}],"meta":{"indicator":"ديسك"}},{"id":30,"mode":"binary","text":"عند انضمام موظف جديد إلى فريقك، قُسّمت عملية تهيئته بينك وبين زميلك؛ فأي جانب تفضل توليه؟","options":[{"text":"تعريفه بمهامه وإجراءاته وأدواته، والتأكد من اكتمال متطلبات مباشرته للعمل.","code":"(I التأثير)"},{"text":"تعريفه بأعضاء الفريق، وبناء تواصل إيجابي معه، ومساعدته على الشعور بالترحيب والانتماء.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":31,"mode":"binary","text":"عند انضمام شخص جديد إلى الفريق، فإن أول ما أبادر إليه غالبًا هو:","options":[{"text":"الترحيب به، وتعريفه بالآخرين، وتشجيعه على الاندماج والمشاركة.","code":"(I التأثير)"},{"text":"مرافقته، والإجابة عن استفساراته، ومساعدته حتى يشعر بالثقة والاستقرار.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":32,"mode":"binary","text":"إذا حصلت على مبلغ مالي وترغب في استثماره في مشروع صغير، فكيف تفضل أن تبدأ؟","options":[{"text":"أفضل البدء بتنفيذه بنفسي، ثم أستعين بالآخرين إذا احتجت لذلك.","code":"المقاتل المنفرد"},{"text":"أبحث منذ البداية عن شركاء مناسبين، وأبني معهم فريقًا لإنجاح المشروع.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":33,"mode":"binary","text":"إذا كان أمامي خياران وظيفيان؛ أحدهما يمنحني فرصة أكبر للتطور وزيادة الدخل لكنه أقل استقرارًا، والآخر أكثر استقرارًا لكن فرص نموه محدودة، فأنا أقرب إلى:","options":[{"text":"اختيار الفرصة التي تمنحني نموًا وخبرة أكبر، حتى لو صاحبها قدر أكبر من المخاطرة وعدم الاستقرار.","code":"(C العاطفي)"},{"text":"اختيار الوظيفة الأكثر استقرارًا ووضوحًا، حتى لو كانت فرص التطور وزيادة الدخل فيها أقل.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":34,"mode":"binary","text":"طُلب من فريقين تطوير أسلوب عمل قائم، ويمكنك الانضمام إلى فريق واحد فقط؛ فأيهما تختار؟","options":[{"text":"فريق يراجع خطوات الأسلوب الحالي، ويعيد ترتيبها وتبسيطها؛ ليصبح أكثر تنظيمًا وسهولة في التنفيذ.","code":"(B التنفيذي)"},{"text":"فريق يعيد تصور العمل من أساسه، ويصمم أسلوبًا مختلفًا يمكن أن يغير طريقة تنفيذه.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":35,"mode":"binary","text":"عند مناقشة موضوع مهم مع مجموعة، فإنني أركز غالبًا على:","options":[{"text":"تنشيط الحوار وتشجيع المشاركين على طرح آرائهم وتبادل وجهات النظر.","code":"(I التأثير)"},{"text":"تنظيم الأفكار المطروحة، وربطها ببعضها للوصول إلى نتيجة واضحة وقابلة للتطبيق.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":36,"mode":"binary","text":"إذا أتقنت مهارة جديدة يحتاجها فريقك في العمل، فما الذي تميل إليه غالبًا؟","options":[{"text":"أحرص على إتقانها وتطبيقها بنفسي في الأعمال المهمة.","code":"القناص"},{"text":"أعمل على نقلها للفريق وأتابع تطبيقهم لها حتى يصبح أداؤهم بالمستوى المطلوب.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":37,"mode":"binary","text":"في مهمة أُعطيت فيها حرية اختيار طريقة التنفيذ، وكان أمامي أسلوب أراه أنسب لي وآخر هو الأسلوب المتعارف عليه في الجهة، فإنني غالبًا:","options":[{"text":"أختار الطريقة التي أراها أنسب وأقرب لأسلوبي، ما دامت تحقق النتيجة المطلوبة.","code":"(B التنفيذي)"},{"text":"أستخدم الأسلوب المتعارف عليه في الجهة؛ لأن توحيد الطريقة والانسجام مع النظام القائم مهمان بالنسبة لي.","code":"(A التحليلي)"}],"meta":{"indicator":"هيرمان"}},{"id":38,"mode":"binary","text":"عند إعداد حملة للتعريف بمبادرة جديدة، عُرض عليك تولي دور واحد فقط؛ فأيهما تفضل؟","options":[{"text":"صياغة الرسالة بما يتناسب مع اهتمامات الجمهور واحتياجاته، وإدارة التواصل والتفاعل معه.","code":"(A التحليلي)"},{"text":"ابتكار مفهوم غير مألوف للحملة، واستخدام صور وتشبيهات تقدم المبادرة من منظور مختلف.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":39,"mode":"binary","text":"عندما يبدأ الفريق العمل بإجراءات جديدة غير معتادة، فإنني أركز غالبًا على:","options":[{"text":"مساعدة الفريق على التعامل معها بهدوء حتى يستقر أسلوب العمل تدريجيًا.","code":"(S الثبات)"},{"text":"ترتيب خطواتها وتوضيح طريقة تطبيقها حتى يتم تنفيذها بدقة.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":40,"mode":"binary","text":"إذا تولى فريقكم تنظيم رحلة، وظهر أن جودة الترتيبات قد تتأثر، فأي الأسلوبين تفضل؟","options":[{"text":"أتدخل لضبط الترتيبات الأساسية حتى تخرج الرحلة بالمستوى المطلوب.","code":"القناص"},{"text":"أوزع مهام التنظيم وأتابع تنفيذها حتى يلتزم الجميع بالمستوى المطلوب.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":41,"mode":"binary","text":"عندما أستغرق وقتًا طويلًا في إنجاز أعمالي، ثم يحين الوقت الذي خصصته للراحة أو لممارسة نشاط أستمتع به، مع بقاء مهمة غير عاجلة لم أنتهِ منها، فإنني غالبًا:","options":[{"text":"أتوقف عن العمل في الوقت الذي حددته للراحة أو الاستمتاع، وأؤجل إكمال المهمة إلى وقت لاحق.","code":"(S الثبات)"},{"text":"أواصل العمل حتى أنتهي من المهمة التي بدأت بها، ثم أخصص وقتي للراحة أو النشاط الذي أستمتع به.","code":"(D الهيمنة)"}],"meta":{"indicator":"ديسك"}},{"id":42,"mode":"binary","text":"تسلّمت تقريرًا يتضمن ملاحظات وتوصيات عديدة، وطُلب منك تولي مهمة واحدة فقط؛ فأيهما تفضل؟","options":[{"text":"مراجعة العلاقة بين الملاحظات والاستنتاجات، والتأكد من أن التوصيات تستند إليها بصورة منطقية.","code":"(A التحليلي)"},{"text":"ترتيب التوصيات حسب الأولوية، وتحويلها إلى مهام ومواعيد ومسؤوليات قابلة للتنفيذ والمتابعة.","code":"(B التنفيذي)"}],"meta":{"indicator":"هيرمان"}},{"id":43,"mode":"binary","text":"إذا واجه الفريق تحديًا مفاجئًا، فإنني غالبًا:","options":[{"text":"أتقدم للمواجهة، وأتحمل مسؤولية دفع العمل نحو نتيجة واضحة.","code":"(D الهيمنة)"},{"text":"أحشد طاقة الفريق وأعزز ثقتهم بقدرتهم على تجاوز التحدي.","code":"(I التأثير)"}],"meta":{"indicator":"ديسك"}},{"id":44,"mode":"binary","text":"إذا واجه فريقك مشكلة عطلت سير العمل، فكيف تفضل التعامل معها؟","options":[{"text":"أنزل مباشرة لمعالجة الخلل حتى يعود العمل إلى مساره.","code":"المقاتل المنفرد"},{"text":"أجمع الفريق وأحفزهم للوصول إلى الحل وتنفيذه.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":45,"mode":"binary","text":"عندما أبدأ مهمة معقدة وقد تظهر أثناء تنفيذها معلومات جديدة لم تكن معروفة من البداية، فإنني غالبًا:","options":[{"text":"أبدأ بما هو متاح، وأعدّل طريقة العمل كلما ظهرت معلومات أو مستجدات جديدة.","code":"(D الإبداعي)"},{"text":"أحرص قبل البدء على وضع خطوات واضحة ومتسلسلة للعمل، ثم ألتزم بها قدر الإمكان أثناء التنفيذ.","code":"(B التنفيذي)"}],"meta":{"indicator":"هيرمان"}},{"id":46,"mode":"binary","text":"ضمن برنامج لتطوير أداء الموظفين، طُلب منك اختيار مسؤولية واحدة فقط؛ فأيهما تفضل؟","options":[{"text":"مراجعة نتائج أداء الموظف ومقارنتها بالمعايير؛ لتحديد جوانب القوة والفجوات التي تحتاج إلى تحسين.","code":"القناص"},{"text":"عقد جلسات تطوير مع الموظف، وفهم التحديات التي يواجهها، ومساعدته على تعزيز ثقته وتحسين أدائه.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":47,"mode":"binary","text":"عندما يحدث خلاف بين أعضاء الفريق، فإنني أميل أكثر إلى:","options":[{"text":"حسم الخلاف واتخاذ القرار الذي يضمن استمرار العمل.","code":"(D الهيمنة)"},{"text":"تقريب وجهات النظر حتى يصل الجميع إلى تفاهم يحافظ على العلاقة.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":48,"mode":"binary","text":"إذا كان لدي جهاز أو غرض ذو قيمة لا أستخدمه حاليًا، وأعرف أن شخصًا قريبًا مني يحتاج إليه فعلًا، فإنني غالبًا:","options":[{"text":"أحتفظ به؛ لأنني قد أحتاج إليه لاحقًا أو أرى أن الاحتفاظ بما أملكه أفضل من التفريط فيه.","code":"(D الهيمنة)"},{"text":"أعطيه للشخص الذي يحتاج إليه الآن، ما دمت لا أستخدمه ويمكن أن ينتفع به أكثر مني.","code":"(I التأثير)"}],"meta":{"indicator":"ديسك"}},{"id":49,"mode":"binary","text":"لديك وقت قصير لعرض فكرة مهمة، وطُلب منك بناء العرض على أسلوب واحد؛ فأيهما تفضل؟","options":[{"text":"تقديم الأدلة والأرقام والنتائج التي تثبت جدوى الفكرة بصورة منطقية.","code":"(A التحليلي)"},{"text":"تقديم تصور ملهم يساعد الحضور على تخيل ما يمكن أن تحققه الفكرة مستقبلًا.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":50,"mode":"binary","text":"إذا أُتيحت للفريق فرصة المشاركة في مبادرة مهمة، وكان موعد التقديم قريبًا، فإنني أميل إلى:","options":[{"text":"المبادرة باقتناص الفرصة، وقيادة التحرك السريع للاستفادة منها.","code":"(D الهيمنة)"},{"text":"مراجعة شروط المبادرة ومتطلباتها، والتأكد من جاهزية الفريق قبل التقديم.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":51,"mode":"binary","text":"إذا كان أحد أعضاء الفريق مسؤولًا عن جزء مهم من مشروع، ثم مر بظرف شخصي صعب قبل موعد التسليم، فإنني غالبًا:","options":[{"text":"أطلب منه أن يوازن قدر الإمكان بين ظرفه الشخصي ومسؤوليته في إنجاز الجزء المطلوب، بحيث يحافظ على موعد التسليم ومستوى العمل.","code":"(S الثبات)"},{"text":"أراعي ظرفه الشخصي، وأمنحه مرونة أكبر؛ كأن أؤخر موعد التسليم، أو أخفف عنه بعض المتطلبات، أو أكلف شخصًا آخر بالمهمة إذا رأى أن ذلك أنسب له.","code":"(D الهيمنة)"}],"meta":{"indicator":"ديسك"}},{"id":52,"mode":"binary","text":"عند تنظيم فعالية مهمة، عُرض عليك الانضمام إلى لجنة واحدة فقط؛ فأيهما تختار؟","options":[{"text":"لجنة التشغيل التي تنظم البرنامج والتجهيزات والمواعيد، وتتابع تنفيذ الفعالية وفق الخطة.","code":"(B التنفيذي)"},{"text":"لجنة تجربة الحاضرين التي تهتم براحتهم وتفاعلهم، وتهيئ أجواء تشجعهم على التواصل والمشاركة.","code":"(C العاطفي)"}],"meta":{"indicator":"هيرمان"}},{"id":53,"mode":"binary","text":"عند التعاون مع أشخاص أتعامل معهم لأول مرة، فإن الأقرب إلى طريقتي هو:","options":[{"text":"المبادرة بالتواصل وكسر الحواجز لبناء علاقة إيجابية بسرعة.","code":"(I التأثير)"},{"text":"منح العلاقة وقتًا كافيًا حتى تتكون الثقة بصورة طبيعية.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":54,"mode":"binary","text":"إذا طُلب منك جمع معلومات عن موضوع مهم سيُبنى عليها قرار، فكيف تفضل تنفيذ ذلك؟","options":[{"text":"أفضل أن أجمع المعلومات وأتحقق من دقتها بنفسي قبل الاعتماد عليها.","code":"القناص"},{"text":"أوزع محاور البحث على الفريق، ثم أراجع معهم النتائج حتى تكتمل الصورة بدقة.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":55,"mode":"binary","text":"في اجتماع تتعدد فيه الآراء ولا يظهر اتجاه واضح للمجموعة، فإنني غالبًا:","options":[{"text":"أتولى توجيه النقاش وأحاول دفع المجموعة نحو الخيار الذي أراه أكثر مناسبة.","code":"(D الهيمنة)"},{"text":"أحرص على أن تُسمع الآراء المختلفة وأتقبل بقاء بعض الاختلاف بينها، حتى لو لم يصل الجميع سريعًا إلى رأي واحد.","code":"(I التأثير)"}],"meta":{"indicator":"ديسك"}},{"id":56,"mode":"binary","text":"عند السفر إلى مكان جديد، عُرض عليك برنامجان لا يمكن الجمع بينهما؛ فأيهما تفضل؟","options":[{"text":"برنامج يحدد الأماكن والمواعيد ومسار التنقل مسبقًا؛ للاستفادة المنظمة من وقت الرحلة.","code":"(B التنفيذي)"},{"text":"برنامج مفتوح يتيح استكشاف المكان وتغيير الوجهة وفق ما يظهر من تجارب وفرص.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":57,"mode":"binary","text":"عند ملاحظة خطأ في عمل أحد الزملاء، فإن أول ما أحرص عليه غالبًا هو:","options":[{"text":"التعامل معه بهدوء ومساندته في تصحيح الخطأ دون إحراج.","code":"(S الثبات)"},{"text":"تحديد موضع الخطأ بدقة، والتأكد من تصحيحه بالطريقة الصحيحة.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":58,"mode":"binary","text":"إذا تعطل جهاز يستخدمه أفراد الأسرة باستمرار، فكيف تفضل التعامل مع المشكلة؟","options":[{"text":"أفضل إصلاحه أو ضبطه بنفسي حتى أطمئن إلى جودة عمله.","code":"الأستاذ"},{"text":"أشرح لأفراد الأسرة طريقة استخدامه والعناية به حتى تقل المشكلات مستقبلاً.","code":"القناص"}],"meta":{"indicator":"الدوافع"}},{"id":59,"mode":"binary","text":"عندما يتم تقديمي في اجتماع رسمي أمام أشخاص لا يعرفونني، فإنني غالبًا:","options":[{"text":"أهتم بذكر مسماي وصفتي وخبرتي؛ لأنها تعكس المستوى والمسؤولية التي وصلت إليها.","code":"(I التأثير)"},{"text":"لا أهتم كثيرًا بذكر مسماي أو صفتي؛ فالأهم بالنسبة لي ما أقدمه من دور وخدمة.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":60,"mode":"binary","text":"بعد انخفاض حماس فريقك تجاه العمل، كانت الفرصة متاحة لتنفيذ نشاط واحد فقط؛ فأيهما تفضل؟","options":[{"text":"عقد جلسة استماع ودعم، تتيح للأعضاء التعبير عن مشاعرهم واحتياجاتهم واستعادة ثقتهم.","code":"(C العاطفي)"},{"text":"عقد ورشة إبداعية تساعد الأعضاء على رؤية التحديات من زوايا مختلفة وتوليد خيارات جديدة.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":61,"mode":"binary","text":"عندما يزداد ضغط العمل على الفريق، فإن أكثر ما أركز عليه غالبًا هو:","options":[{"text":"المحافظة على هدوء الفريق وتقديم الدعم حتى يستمر العمل بتوازن.","code":"(S الثبات)"},{"text":"ترتيب الأولويات ومتابعة التفاصيل المهمة حتى لا تتأثر جودة العمل.","code":"(D الهيمنة)"}],"meta":{"indicator":"ديسك"}},{"id":62,"mode":"binary","text":"إذا كنت تعمل على تصميم مهم سيُعرض على عدد كبير من الأشخاص، فكيف تفضل تنفيذه؟","options":[{"text":"أفضل تنفيذ التصميم بنفسي حتى يخرج بأعلى جودة.","code":"القناص"},{"text":"أقود فريق التصميم، وأتابع جودة العمل حتى يخرج بالمستوى المطلوب.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":63,"mode":"binary","text":"بعد أن أتمكن جيدًا من مجال معين، ثم تتاح لي فرصة لتعلم مجال جديد يختلف عنه ويحتاج مني إلى البدء من مستوى أقل، فإنني غالبًا:","options":[{"text":"أخوض المجال الجديد؛ لأن اكتساب خبرات مختلفة وتوسيع معرفتي أمر مهم بالنسبة لي.","code":"(S الثبات)"},{"text":"أفضّل الاستمرار في المجال الذي أعرفه وأتقنه وتطوير خبرتي داخله؛ لأن العمل ضمن مجال مألوف يمنحني ثقة ووضوحًا أكبر.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":64,"mode":"binary","text":"بعد انتهاء مشروع مهم، لم يتبقَّ لك وقت إلا لتولي مهمة ختامية واحدة، بينما يتولى زميلك المهمة الأخرى؛ فأيهما تختار؟","options":[{"text":"تحليل مؤشرات المشروع، ومقارنة نتائجه بأهدافه، وتفسير أسباب الفروق التي ظهرت بينهما.","code":"المقاتل المنفرد"},{"text":"إغلاق المشروع تنظيميًا، والتأكد من اكتمال مهامه ووثائقه، وتسليم مخرجاته، وحصر ما تبقى من إجراءات.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":65,"mode":"binary","text":"عند حدوث تغيير مفاجئ في الخطة، فإن أولويتي غالبًا تكون في:","options":[{"text":"المبادرة بتوجيه الفريق واتخاذ القرارات اللازمة للانتقال إلى الخطة الجديدة.","code":"(D الهيمنة)"},{"text":"مساعدة الفريق على التكيف مع التغيير تدريجيًا والمحافظة على استقرار العمل.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":66,"mode":"binary","text":"إذا كان أمامك قرار مهم يحتاج إلى سرعة في الحسم، فكيف تفضل اتخاذه؟","options":[{"text":"أحسم القرار، وأبدأ بتنفيذه مباشرة.","code":"المقاتل المنفرد"},{"text":"أشرك الفريق في مناقشته حتى يلتزم الجميع بتنفيذه.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":67,"mode":"binary","text":"عندما أكون أمام قرار مهم يتعلق بطريقة عيشي أو مستقبلي، ويكون اختياري الشخصي مختلفًا عن التقاليد التي نشأت عليها، فإنني غالبًا:","options":[{"text":"أختار ما أراه مناسبًا لي وفق قناعتي، حتى لو كان مختلفًا بوضوح عن التقاليد السائدة في أسرتي أو مجتمعي.","code":"(I التأثير)"},{"text":"أتمسك بالتقاليد التي نشأت عليها، وأختار ما ينسجم معها حتى لو كان ذلك مخالفًا لما أميل إليه شخصيًا.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":68,"mode":"binary","text":"قبل تطبيق تغيير مهم في جهة عملك، طُلب منك إعداد دراسة واحدة فقط؛ فأيهما تختار؟","options":[{"text":"دراسة النتائج المتوقعة من التغيير، ومقارنة مكاسبه ومخاطره؛ لتقدير مدى جدواه.","code":"(D الهيمنة)"},{"text":"عقد جلسات استماع مع الموظفين، وفهم مخاوفهم واحتياجاتهم، والمحافظة على ثقتهم وتفاعلهم أثناء التغيير.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":69,"mode":"binary","text":"إذا تعلمت أسلوبًا جديدًا يسرع إنجاز العمل، فكيف تفضل الاستفادة منه؟","options":[{"text":"أبادر إلى تطبيقه في أعمالي لتحقيق نتائج أسرع.","code":"المقاتل المنفرد"},{"text":"أنقله إلى الفريق، وأشجعهم على الاستفادة منه في أعمالهم.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":70,"mode":"binary","text":"عندما أكون في رحلة أو إجازة، وتوجد أعمال غير عاجلة يمكن متابعتها عن بُعد، فإنني غالبًا:","options":[{"text":"أتركها إلى ما بعد الإجازة، وأحرص على أن يكون وقت الرحلة مخصصًا للراحة والاستمتاع دون انشغال مستمر بالعمل.","code":"المقاتل المنفرد"},{"text":"أخصص وقتًا محددًا أثناء الإجازة لمتابعة هذه الأعمال؛ حتى أبقى ملتزمًا بمسؤولياتي ولا تتراكم عليّ بعد العودة.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":71,"mode":"binary","text":"قبل اعتماد فكرة جديدة لم تُجرَّب من قبل، وكانت الموارد المتاحة لا تسمح إلا بأحد الخيارين، فأيهما تفضل؟","options":[{"text":"إجراء دراسة تقارن بين نتائج الفكرة المتوقعة ومخاطرها، بالاستناد إلى المعلومات المتاحة.","code":"(A التحليلي)"},{"text":"تطبيق الفكرة على نطاق محدود؛ لاختبارها عمليًا واستكشاف ما قد تتيحه من استخدامات وفرص جديدة.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":72,"mode":"binary","text":"أردت القيام برحلة استكشافية إلى مكان جديد، فأيهما تستمتع به أكثر؟","options":[{"text":"أن أتولى تخطيط الرحلة وإدارتها خطوة بخطوة.","code":"المقاتل المنفرد"},{"text":"أن أقود مجموعة، وأجعل نجاح الرحلة ثمرة لتعاون الجميع.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":73,"mode":"binary","text":"أثناء تنفيذ مشروع وفق خطة معتمدة، ظهرت فرصة لتنفيذ بعض الأعمال بطريقة مختلفة قد توفر وقتًا وتناسب الظروف الحالية، لكنها ستغيّر جزءًا من تسلسل الخطة المتفق عليها، فإنني غالبًا:","options":[{"text":"أعدّل ترتيب بعض الخطوات وأستفيد من الطريقة الجديدة ما دامت تساعد على إنجاز المشروع بصورة أفضل.","code":"المقاتل المنفرد"},{"text":"أستمر وفق تسلسل الخطة المعتمدة كما وُضع من البداية؛ لأن وضوح المنهج وثباته يساعدان على ضبط التنفيذ وتقليل الأخطاء.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":74,"mode":"binary","text":"طُلب منك اختيار طريقة واحدة لتعريف فريقك بمهمة جديدة؛ فأيهما تفضل؟","options":[{"text":"إعداد دليل واضح يبين خطوات المهمة ومعاييرها، وما يجب إنجازه في كل مرحلة.","code":"القناص"},{"text":"عقد لقاء تفاعلي يتيح للأعضاء مناقشة المهمة وطرح أسئلتهم والتعبير عن احتياجاتهم قبل البدء.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":75,"mode":"binary","text":"إذا لاحظت انخفاض حماس الفريق، فإنني غالبًا:","options":[{"text":"أبث الحماس، وأحفزهم، وأشجعهم على مواصلة العمل بروح إيجابية.","code":"(I التأثير)"},{"text":"أساعد الفريق على استعادة هدوئه وتوازنه، والمحافظة على وتيرة عمل مستقرة.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":76,"mode":"binary","text":"إذا استعد فريق دراسي لاختبار مهم، وطُلب منك المساعدة في رفع مستوى المجموعة، فكيف تفضل المساهمة؟","options":[{"text":"أعد ملخصًا ومراجعة متقنة يعتمد عليها الجميع في الاستعداد للاختبار.","code":"القناص"},{"text":"أنظم جلسات مراجعة، وأشرح للزملاء، وأتابع فهمهم حتى يرتفع مستوى المجموعة.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":77,"mode":"binary","text":"إذا طلب مني شخص أن أخصص عدة ساعات لتعليمه مهارة أتقنها، وكانت هذه الساعات مخصصة لعمل شخصي يمكن أن يعود عليّ بعائد أو منفعة واضحة، فإنني غالبًا:","options":[{"text":"أحتفظ بالوقت لما خططت له، وأستخدمه في العمل الذي يعود عليّ بالمنفعة الشخصية.","code":"(S الثبات)"},{"text":"أخصص جزءًا من الوقت لتعليمه ومساعدته، حتى لو اضطررت إلى تأجيل بعض ما كان سيعود عليّ بمنفعة.","code":"(D الهيمنة)"}],"meta":{"indicator":"ديسك"}},{"id":78,"mode":"binary","text":"عند إعداد خطة جهة عملك للعام القادم، عُرض عليك تولي دور واحد فقط؛ فأيهما تفضل؟","options":[{"text":"إعداد الجدول التنفيذي للبرامج المعتمدة، وتحديد مهامها ومواردها ومواعيد إنجازها.","code":"(B التنفيذي)"},{"text":"استشراف المتغيرات والفرص المستقبلية، واقتراح مبادرات واتجاهات جديدة للجهة.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":79,"mode":"binary","text":"عند المشاركة في تنفيذ مشروع جماعي، فإن الدور الأقرب لطريقتي هو:","options":[{"text":"تنسيق التواصل بين أعضاء الفريق وتعزيز التعاون بينهم.","code":"(I التأثير)"},{"text":"متابعة سير التنفيذ والتأكد من أن العمل يسير بصورة منظمة ومتقنة.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":80,"mode":"binary","text":"أصبحت متمكنًا من إحدى هواياتك، وطلب منك نادي الهواية تنفيذ عمل مشترك، فهل:","options":[{"text":"أفضل أن أتولى تنفيذ العمل؛ لأضمن خروجه بالمستوى الذي أطمح إليه.","code":"القناص"},{"text":"أفضل توزيع العمل على المجموعة وتوجيههم وتدريبهم حتى يظهر العمل بأفضل صورة.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":81,"mode":"binary","text":"إذا كان لدي في يوم واحد وقت إضافي محدود لا يكفي إلا لأحد أمرين: إما استخدامه لتطوير مهارة مهمة ورفع مستوى أدائي، أو تخصيصه لمساندة شخص قريب يمر بظرف يحتاج فيه إلى دعمي، فإنني غالبًا:","options":[{"text":"أستخدم الوقت في تطوير مهارتي ورفع مستوى أدائي؛ لأن التقدم والتميز في ما أفعله يمثلان أولوية مهمة لي.","code":"(S الثبات)"},{"text":"أخصص الوقت لمساندة الشخص والوقوف معه، وأؤجل تطوير مهارتي إلى وقت آخر؛ لأن حاجته للدعم الآن أكثر أولوية لدي.","code":"(D الهيمنة)"}],"meta":{"indicator":"ديسك"}},{"id":82,"mode":"binary","text":"بعد قراءة قصة، طُلب منك اختيار جانب واحد فقط لمناقشته؛ فأيهما تفضل؟","options":[{"text":"مشاعر الشخصيات، والتغيرات التي طرأت على علاقاتها، وأثر الأحداث فيها.","code":"(C العاطفي)"},{"text":"الأفكار والرموز التي تحملها القصة، والاحتمالات والتصورات الجديدة التي يمكن استخلاصها منها.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":83,"mode":"binary","text":"إذا طُلب منك اختيار جهاز سيعتمد عليه فريق العمل لسنوات، فكيف تفضل اتخاذ القرار؟","options":[{"text":"أتولى بنفسي مقارنة الخيارات والتأكد من أدق التفاصيل قبل اختيار الجهاز.","code":"القناص"},{"text":"أشرك الفريق في تقييم الخيارات حتى نصل إلى أفضل قرار يناسب الجميع.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":84,"mode":"binary","text":"إذا اتخذت مجموعة أعمل معها قرارًا مهمًا لا يتفق مع الخيار الذي كنت أؤيده، وكانت لدي علاقات أو مكانة تمكنني من محاولة تغيير القرار، فإنني غالبًا:","options":[{"text":"أستخدم قدرتي على التأثير وأحاول إعادة توجيه القرار نحو الخيار الذي أراه أفضل.","code":"(D الهيمنة)"},{"text":"أتقبل القرار الذي توصلت إليه المجموعة، حتى لو بقي رأيي مختلفًا ولم يكن هو الخيار الذي تم اعتماده.","code":"(I التأثير)"}],"meta":{"indicator":"ديسك"}},{"id":85,"mode":"binary","text":"عند المشاركة في مبادرة مجتمعية جديدة، عُرض عليك تولي دور واحد فقط؛ فأيهما تختار؟","options":[{"text":"بناء العلاقات مع الشركاء والمتطوعين، وتعزيز التواصل والتعاون بينهم طوال المبادرة.","code":"(I التأثير)"},{"text":"جمع أفكار من مجالات مختلفة ودمجها في تصور مبتكر يميز المبادرة عن غيرها.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":86,"mode":"binary","text":"إذا طُلب منك تجهيز مكتبة صغيرة ليستفيد منها مجموعة من الأشخاص، فكيف تفضل تنفيذ ذلك؟","options":[{"text":"أتولى اختيار الكتب والمراجع بنفسي حتى أضمن جودة المحتوى.","code":"القناص"},{"text":"أشرك المجموعة في اختيار المحتوى، وأوجههم حتى تصبح المكتبة مناسبة للجميع.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":87,"mode":"binary","text":"إذا كنت في دور مهني مستقر أؤدي فيه عملًا نافعًا، ثم أتيحت لي فرصة للترشح لمنصب أعلى يتطلب مسؤوليات وضغطًا أكبر، فإنني غالبًا:","options":[{"text":"أتقدم للمنصب الأعلى؛ لأن التقدم إلى مستويات أكبر من المسؤولية والمكانة يمثل هدفًا مهمًا بالنسبة لي.","code":"(D الهيمنة)"},{"text":"أستمر في دوري الحالي إذا كنت أرى أنني أقدم فيه خدمة وقيمة حقيقية، ولا أعد الوصول إلى منصب أعلى ضرورة بالنسبة لي.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":88,"mode":"binary","text":"إذا توفر لدي مبلغ مالي زائد عن احتياجاتي الحالية، فإنني غالبًا:","options":[{"text":"أحتفظ به للادخار أو أستخدمه في تحسين وضعي المادي واحتياجاتي المستقبلية.","code":"(I التأثير)"},{"text":"أخصص جزءًا منه لمساعدة شخص محتاج أو دعم عمل أرى أن له فائدة واضحة للآخرين.","code":"(D الهيمنة)"}],"meta":{"indicator":"ديسك"}},{"id":89,"mode":"rank","text":"عند المشاركة في مشروع لدراسة إحدى المناطق الطبيعية، رتّب المهام التالية بحسب ما تستمتع به أكثر:","options":[{"text":"العمل في الموقع، وجمع العينات، واستخدام الأدوات الميدانية اللازمة.","code":"R"},{"text":"توعية الزوار بأهمية المحافظة على الموقع، والإجابة عن أسئلتهم.","code":"S"},{"text":"فحص العينات والبيانات، وتحليل العوامل المؤثرة في البيئة الطبيعية.","code":"I"},{"text":"تصوير الموقع وإعداد قصة بصرية تُبرز طبيعته وجماله.","code":"A"}],"meta":{"indicator":"هولاند"}},{"id":90,"mode":"rank","text":"عند المشاركة في تطوير منتج جديد، رتّب المهام التالية بحسب ما تستمتع به أكثر:","options":[{"text":"دراسة احتياجات المستخدمين، وتحليل المعلومات للتأكد من جدوى المنتج.","code":"I"},{"text":"تحويل الفكرة إلى مشروع، وعرضها على الجهات التي يمكن أن تدعمها أو تستثمر فيها.","code":"E"},{"text":"صناعة نموذج أولي للمنتج باستخدام الأدوات، وتجربته بصورة عملية.","code":"R"},{"text":"ابتكار شكل المنتج، وتصميم هويته وطريقة عرضه بأسلوب مميز.","code":"A"}],"meta":{"indicator":"هولاند"}},{"id":91,"mode":"rank","text":"عند إعادة تجهيز مكتب أو قاعة عمل، رتّب المهام التالية بحسب ما تستمتع به أكثر:","options":[{"text":"تصوّر الشكل الجديد للمكان، وابتكار تصميم يجمع بين الجمال والاستفادة الجيدة من المساحة.","code":"A"},{"text":"تحديد المقاسات والمواد والتكاليف، ووضع خطوات التنفيذ ومواعيده.","code":"C"},{"text":"استخدام الأدوات في تركيب الأثاث والتجهيزات، وتنفيذ التعديلات المطلوبة بيدي.","code":"R"},{"text":"دراسة كيفية استخدام المكان حاليًا، وتحديد مشكلاته، والتحقق من أن التصميم الجديد سيعالجها.","code":"I"}],"meta":{"indicator":"هولاند"}},{"id":92,"mode":"rank","text":"عند المشاركة في مبادرة لتطوير أحد المرافق العامة، رتّب الأدوار التالية بحسب تفضيلك:","options":[{"text":"العمل في الموقع، واستخدام الأدوات لتنفيذ التحسينات المطلوبة.","code":"R"},{"text":"الاستماع إلى مستخدمي المرفق، وفهم احتياجاتهم، ومساعدتهم على الاستفادة منه.","code":"S"},{"text":"جمع البيانات عن استخدام المرفق، ومقارنة بدائل التطوير لتحديد التحسين الأكثر فائدة.","code":"I"},{"text":"قيادة المبادرة، وعرضها على الجهات المعنية، والعمل على كسب دعمها.","code":"E"}],"meta":{"indicator":"هولاند"}},{"id":93,"mode":"rank","text":"عندما تواجه جهة العمل مشكلة أدت إلى تعطّل بعض أعمالها، رتّب الأدوار التالية بحسب تفضيلك:","options":[{"text":"تحليل المشكلة، والبحث عن أسبابها الجذرية قبل اختيار الحل المناسب.","code":"I"},{"text":"قيادة الموقف، وحشد الفريق، واتخاذ الخطوات اللازمة لاستعادة سير العمل.","code":"E"},{"text":"فحص موقع التعطّل، واستخدام الأدوات أو المعدات لتنفيذ المعالجة المطلوبة.","code":"R"},{"text":"مساعدة المتأثرين بالمشكلة، والاستماع إليهم، ودعمهم حتى يتجاوزوها.","code":"S"}],"meta":{"indicator":"هولاند"}},{"id":94,"mode":"rank","text":"عند إعداد عرض مسرحي تربوي للأطفال، رتّب المهام التالية بحسب تفضيلك:","options":[{"text":"تدريب الأطفال على أدوارهم، وتشجيعهم، ومساعدتهم على تحسين أدائهم.","code":"S"},{"text":"كتابة فكرة العرض، وابتكار الشخصيات والمشاهد وطريقة تقديمها.","code":"A"},{"text":"تنظيم مواعيد التدريبات، وتوزيع الأدوار، ومتابعة جاهزية العرض.","code":"C"},{"text":"تجهيز المسرح، وتركيب الديكورات والإضاءة والمعدات المستخدمة.","code":"R"}],"meta":{"indicator":"هولاند"}},{"id":95,"mode":"rank","text":"عند المشاركة في تشغيل مزرعة إنتاجية حديثة، رتّب المهام التالية بحسب ما تستمتع به أكثر:","options":[{"text":"زراعة المحاصيل، وتشغيل معدات الري، ومتابعة الأعمال الميدانية.","code":"R"},{"text":"إرشاد العاملين، وتعليمهم طرق العناية بالمحاصيل والسلامة أثناء العمل.","code":"S"},{"text":"فحص التربة والمحاصيل، وتحليل أسباب ضعف الإنتاج، وتجربة الحلول المناسبة.","code":"I"},{"text":"تسجيل كميات الإنتاج والمصروفات، وتنظيم سجلات المخزون والمبيعات.","code":"C"}],"meta":{"indicator":"هولاند"}},{"id":96,"mode":"rank","text":"عند اختيار جهاز أو نظام تقني ستعتمد عليه جهة العمل، رتّب المهام التالية بحسب ما تستمتع به أكثر:","options":[{"text":"مقارنة المواصفات، واختبار البدائل، وتحليل النتائج قبل الاختيار.","code":"I"},{"text":"التفاوض مع الموردين للحصول على أفضل عرض وشروط ممكنة.","code":"E"},{"text":"تجربة الجهاز وتركيبه والتأكد عمليًا من كفاءته وسهولة تشغيله.","code":"R"},{"text":"تنظيم العروض والعقود والفواتير وسجلات الضمان والصيانة.","code":"C"}],"meta":{"indicator":"هولاند"}},{"id":97,"mode":"rank","text":"عند المشاركة في تشغيل مشروع تجاري صغير، رتّب المهام التالية بحسب ما تستمتع به أكثر:","options":[{"text":"تنظيم الطلبات والمخزون والسجلات وإجراءات التشغيل اليومية.","code":"C"},{"text":"تصميم هوية المشروع ومحتواه وطريقة ظهوره أمام العملاء.","code":"A"},{"text":"تجهيز المنتجات واستخدام الأدوات والمعدات اللازمة لإعدادها.","code":"R"},{"text":"تسويق المشروع والتفاوض مع العملاء واستثمار فرص التوسع.","code":"E"}],"meta":{"indicator":"هولاند"}},{"id":98,"mode":"rank","text":"عند تنظيم فعالية ثقافية وإبداعية، رتّب الأدوار التالية بحسب تفضيلك:","options":[{"text":"تجهيز الموقع وتركيب الأركان والأدوات اللازمة لإقامة الفعالية.","code":"R"},{"text":"مساعدة المشاركين والمتطوعين، وتقديم الدعم لهم أثناء تنفيذ الفعالية.","code":"S"},{"text":"كتابة محتوى الفعالية وتصميم عروضها وتصوير أنشطتها بأسلوب إبداعي.","code":"A"},{"text":"قيادة الترويج للفعالية، والتفاوض مع الداعمين، واستقطاب المشاركين.","code":"E"}],"meta":{"indicator":"هولاند"}},{"id":99,"mode":"rank","text":"عند إعداد حملة توعوية حول موضوع مهم، رتّب المهام التالية بحسب تفضيلك:","options":[{"text":"القراءة في الموضوع، والبحث في مصادره، والتحقق من صحة المعلومات المتعلقة به.","code":"I"},{"text":"تقديم الحملة أمام الجمهور، وعرض رسالتها بطريقة تؤثر فيهم وتقنعهم بها.","code":"E"},{"text":"كتابة محتوى الحملة وتصميم صورها ومقاطعها بأسلوب إبداعي.","code":"A"},{"text":"تنفيذ اللقاءات التوعوية، والإجابة عن أسئلة المستفيدين، ومساعدتهم على التطبيق.","code":"S"}],"meta":{"indicator":"هولاند"}},{"id":100,"mode":"rank","text":"عند إعداد مجلة معرفية، رتّب المهام التالية بحسب ما تستمتع به أكثر:","options":[{"text":"تنظيم أبواب المجلة ومواعيد التسليم، ومراجعة اكتمال المواد قبل النشر.","code":"C"},{"text":"البحث في المصادر، والتحقق من المعلومات، ومقارنة الآراء المتعلقة بالموضوعات المنشورة.","code":"I"},{"text":"كتابة مقال أو قصة بأسلوب تعبيري يجذب القارئ ويعكس رؤيتي الخاصة.","code":"A"},{"text":"إجراء مقابلات مع أشخاص مختلفين، والاستماع إلى تجاربهم، ومساعدتهم على عرض أفكارهم بوضوح.","code":"S"}],"meta":{"indicator":"هولاند"}},{"id":101,"mode":"rank","text":"عند إقامة ورشة تطبيقية لصناعة منتج بسيط، رتّب المهام التالية بحسب ما تستمتع به أكثر:","options":[{"text":"استخدام الأدوات والمواد لصناعة المنتج وتجميع أجزائه بصورة عملية.","code":"R"},{"text":"تعليم المشاركين خطوات العمل، ومساعدتهم على تطوير مهاراتهم أثناء التطبيق.","code":"S"},{"text":"ابتكار شكل المنتج وإضافة أفكار ولمسات فنية تجعله مختلفًا.","code":"A"},{"text":"ترتيب الأدوات والمواد، وتنظيم خطوات العمل، ومراجعة اكتمال كل مرحلة.","code":"C"}],"meta":{"indicator":"هولاند"}},{"id":102,"mode":"rank","text":"عند اقتراح مبادرة لتطوير العمل، رتّب المهام التالية بحسب ما تستمتع به أكثر:","options":[{"text":"دراسة المؤشرات والمعلومات المتاحة لتحديد المشكلة والاحتياج بدقة.","code":"I"},{"text":"عرض المبادرة على أصحاب القرار، وإقناعهم بأهميتها، والعمل على كسب دعمهم.","code":"E"},{"text":"ابتكار فكرة جديدة للمبادرة، وتقديمها بطريقة مختلفة عن الأساليب المعتادة.","code":"A"},{"text":"إعداد مراحل المبادرة ومواعيدها وميزانيتها وآلية متابعة تنفيذها.","code":"C"}],"meta":{"indicator":"هولاند"}},{"id":103,"mode":"rank","text":"عند المشاركة في مسابقة للابتكار، رتّب المهام التالية بحسب ما تستمتع به أكثر:","options":[{"text":"توليد فكرة جديدة، وتصميم حل مختلف وغير مألوف للمشكلة المطروحة.","code":"A"},{"text":"إعداد خطة المشروع ونماذج التقديم ووثائقه وفق متطلبات المسابقة ومواعيدها.","code":"C"},{"text":"إجراء التجارب واختبار الحل المقترح، وتحليل النتائج للتحقق من فاعليته.","code":"I"},{"text":"تقديم الفكرة أمام لجنة التحكيم، والدفاع عنها، وإقناع اللجنة بقيمتها.","code":"E"}],"meta":{"indicator":"هولاند"}},{"id":104,"mode":"rank","text":"عند تنفيذ حملة ميدانية لخدمة مجموعة من المستفيدين، رتّب الأدوار التالية بحسب تفضيلك:","options":[{"text":"تجهيز المواد ونقلها وترتيب موقع العمل والتوزيع بصورة ميدانية.","code":"R"},{"text":"مقابلة المستفيدين والاستماع إلى احتياجاتهم وتقديم المساعدة المناسبة لهم.","code":"S"},{"text":"قيادة فريق الحملة، وتوزيع المسؤوليات، والتواصل مع الجهات المشاركة.","code":"E"},{"text":"تسجيل بيانات المستفيدين، ومراجعة الكميات، وتنظيم سجلات الاستلام والتسليم.","code":"C"}],"meta":{"indicator":"هولاند"}},{"id":105,"mode":"rank","text":"عند مراجعة انخفاض نتائج أحد فرق العمل، رتّب الأدوار التالية بحسب تفضيلك:","options":[{"text":"تحليل الأرقام ومؤشرات الأداء، ومقارنة النتائج؛ لتحديد أسباب الانخفاض.","code":"I"},{"text":"اتخاذ القرارات اللازمة، وتحديد النتائج المستهدفة، وتحفيز الفريق على تحقيقها.","code":"E"},{"text":"تدريب أعضاء الفريق، ومناقشة صعوباتهم، ومساعدتهم على تحسين أدائهم.","code":"S"},{"text":"مراجعة إجراءات العمل والسجلات، والتأكد من تنفيذ المهام وفق المتطلبات المحددة.","code":"C"}],"meta":{"indicator":"هولاند"}},{"id":106,"mode":"rank","text":"عند تنظيم برنامج مجتمعي جديد، رتّب الأدوار التالية بحسب تفضيلك:","options":[{"text":"ابتكار فكرة البرنامج، وتصميم أنشطته ومحتواه بطريقة إبداعية.","code":"A"},{"text":"تنظيم التسجيل والمواعيد والميزانية والتجهيزات، ومتابعة تنفيذ الخطة.","code":"C"},{"text":"التواصل مع المشاركين، والاستماع إلى احتياجاتهم، وتقديم الدعم لهم.","code":"S"},{"text":"قيادة البرنامج، واستقطاب الشركاء، والترويج له، وتوسيع فرص نجاحه.","code":"E"}],"meta":{"indicator":"هولاند"}},{"id":107,"mode":"scale","text":"إذا كُلِّفت بمهمة جديدة لا تتوفر لها تعليمات تفصيلية، أبادر إلى البدء في تنفيذها وفق أفضل ما يتوافر لدي من معطيات، حتى لو استلزم ذلك تحمل مسؤولية بعض الاجتهادات أثناء التنفيذ.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الحادية عشرة: إدارة التغيير"}},{"id":108,"mode":"scale","text":"أستمتع بقراءة القصص والمقالات، وأنتبه إلى معاني الكلمات وطريقة صياغة الأفكار، ثم أعبّر عما فهمته بأسلوبي.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":109,"mode":"scale","text":"إذا وقع خطأ كنت طرفًا فيه، أتحمل مسؤوليتي وأسعى إلى معالجته، حتى عندما تكون هناك ظروف أو عوامل أخرى أسهمت في حدوثه.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثانية: تحمل المسؤولية"}},{"id":110,"mode":"scale","text":"إذا واجهت عدة مهام جميعها تبدو عاجلة ومهمة، أخصص وقتًا لتحديد أولوياتها وترتيب خطوات تنفيذها قبل البدء، رغم الضغوط التي تدفعني إلى البدء فورًا في مهمة يراها الآخرون أكثر أهمية.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثانية: تحمل المسؤولية"}},{"id":111,"mode":"scale","text":"أتحكم بحركة يدي بدقة عند أداء مهام مثل توجيه الكرة نحو هدف، أو تركيب قطع صغيرة، أو القص والرسم على خطوط محددة.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الحركي"}},{"id":112,"mode":"scale","text":"إذا سنحت لي فرصة لتجاوز إجراء أو نظام دون أن يلاحظ أحد ذلك، وكان تجاوزه سيسرع إنجاز العمل، ألتزم بالأنظمة والإجراءات رغم ما قد يسببه ذلك من تأخير أو جهد إضافي.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الرابعة: النزاهة والموثوقية"}},{"id":113,"mode":"scale","text":"إذا كنت مسؤولًا عن شرح قرار سيؤثر في عدة إدارات أو فرق عمل، أتحقق من أن كل جهة فهمت دورها بالطريقة المقصودة، حتى لو أدى ذلك إلى تأخير التنفيذ أو إعادة توضيح القرار أكثر من مرة.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الأولى: المبادرة"}},{"id":114,"mode":"scale","text":"عند تحمّل مسؤولية جديدة، أعرف ما يمكنني إنجازه بكفاءة، وما يحتاج مني إلى تعلّم إضافي أو طلب المساعدة.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الذاتي"}},{"id":115,"mode":"scale","text":"إذا كنت مقتنعًا بفكرة تطويرية وعرضتها على أصحاب القرار ولم تحظَ بالقبول في البداية، أواصل العمل على تحسين طريقة عرضها وجمع ما يدعمها قبل إعادة طرحها، بدلًا من التخلي عنها.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثالثة: التخطيط والتنظيم"}},{"id":116,"mode":"scale","text":"إذا سنحت فرصة لإشراك أحد أفراد الفريق في مهمة جديدة تساعده على اكتساب خبرة، أمنحه هذه الفرصة، رغم أن إسنادها إلى شخص أكثر خبرة قد يحقق إنجازها بشكل أفضل وبسرعة أكبر.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة السابعة: تطوير الآخرين"}},{"id":117,"mode":"scale","text":"أفهم الخرائط والمخططات بسهولة، وأستطيع استخدامها لتحديد المواقع والاتجاهات أو الوصول إلى مكان لم أزره من قبل.","meta":{"indicator":"الذكاءات","dimension":"الذكاء البصري"}},{"id":118,"mode":"scale","text":"إذا تطلب إنجاز العمل التعاون مع أشخاص تختلف آراؤهم أو أساليبهم عن أسلوبي، أتعاون معهم لتحقيق الهدف المشترك، حتى لو كنت أعتقد أن إنجاز المهمة بمفردي سيكون أسرع أو أسهل.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثامنة: العمل الجماعي"}},{"id":119,"mode":"scale","text":"إذا كنت المسؤول عن اتخاذ قرار عاجل يترتب عليه نتائج مؤثرة، ولا تتوافر جميع المعلومات اللازمة، أتخذ القرار في الوقت المناسب، وأتحمل مسؤوليته دون انتظار اكتمال الصورة.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة التاسعة: اتخاذ القرار"}},{"id":120,"mode":"scale","text":"أستمتع بالعمل ضمن فريق؛ فأشارك أفكاري، وأستمع إلى آراء الآخرين، وأتعاون معهم في توزيع الأدوار وحل الخلافات حتى نحقق الهدف المشترك.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الاجتماعي"}},{"id":121,"mode":"scale","text":"عندما تواجه جهة عملي مشكلة معقدة، يُطلب مني غالبًا المشاركة في تحليلها أو المساهمة في معالجتها؛ لثقة الآخرين بقدرتي على التعامل معها.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة العاشرة: حل المشكلات"}},{"id":122,"mode":"scale","text":"إذا كنت مسؤولًا عن تنفيذ عمل اعتاد الجميع على طريقته، وتبين لي أن هناك حاجة للتغيير، أبادر إلى تطبيق التغيير، رغم ما قد يترتب عليه من اعتراضات، أو زيادة في الجهد، أو تحمل مسؤولية نتائجه في مراحله الأولى.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الحادية عشرة: إدارة التغيير"}},{"id":123,"mode":"scale","text":"عندما أراجع أرقامًا أو بيانات، أستطيع حساب الفروق والنسب بينها، وملاحظة اتجاه الزيادة أو الانخفاض للوصول إلى نتيجة واضحة.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الرياضي"}},{"id":124,"mode":"scale","text":"إذا طُلب مني تنفيذ مهمة بشكل عاجل، أحرص أولًا على فهم ارتباطها بالأهداف الإستراتيجية والنتائج بعيدة المدى، حتى لو أدى ذلك إلى تأخير البدء في التنفيذ.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثانية عشرة: التفكير الاستراتيجي والاستشراف"}},{"id":125,"mode":"scale","text":"إذا لاحظت فرصة لتحسين العمل، أبادر بطرحها والسعي إلى تطبيقها، رغم أنها ليست ضمن المهام المطلوبة مني.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الأولى: المبادرة"}},{"id":126,"mode":"scale","text":"أستطيع ابتكار إيقاع أو لحن بسيط يناسب مجموعة من الكلمات، أو تعديل طريقة أدائها حتى تصبح أكثر انسجامًا وإيقاعًا.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":127,"mode":"scale","text":"إذا واجهت صعوبات أو ظروفًا غير متوقعة أثناء تنفيذ مهمة أوكلت إليّ، أواصل العمل وأبحث عن الحلول المناسبة لإتمامها، رغم أن إسنادها إلى شخص آخر أكثر خبرة قد يكون أسرع أو أسهل.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثانية: تحمل المسؤولية"}},{"id":128,"mode":"scale","text":"إذا كنت مسؤولًا عن عمل يعتمد على عدة أشخاص، أحرص على تحديد الأدوار وآلية المتابعة قبل البدء، حتى عندما يطالب بعض أعضاء الفريق بالبدء أولًا وتأجيل توزيع المسؤوليات إلى أثناء التنفيذ.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثالثة: التخطيط والتنظيم"}},{"id":129,"mode":"scale","text":"عندما أريد إقناع الآخرين بفكرة، أرتب حججي وأستخدم كلمات وأمثلة تدعم وجهة نظري وتوضحها.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":130,"mode":"scale","text":"إذا التزمت بإنجاز عمل أو تسليمه في وقت محدد، أوفي بالتزامي، حتى لو اضطررت إلى تأجيل بعض خططي أو مصالحي الشخصية أو بذل جهد إضافي خارج وقت العمل.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الرابعة: النزاهة والموثوقية"}},{"id":131,"mode":"scale","text":"إذا أصبح أحد أفراد الفريق مؤهلًا لتحمل مسؤوليات أكبر، أفوضه بمهام مؤثرة تساعده على النمو، حتى لو كان احتفاظي بها يحقق نتائج أسرع أو أكثر استقرارًا.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة السابعة: تطوير الآخرين"}},{"id":132,"mode":"scale","text":"أستطيع تخيّل الشكل النهائي للأشياء قبل تنفيذها؛ مثل تصميم منتج، أو إعداد عرض مرئي، أو تنظيم مساحة معينة.","meta":{"indicator":"الذكاءات","dimension":"الذكاء البصري"}},{"id":133,"mode":"scale","text":"إذا كانت لدي معرفة أو خبرة يحتاجها الفريق لتحقيق نتائج أفضل، أشاركها مع الجميع، حتى لو أدى ذلك إلى تقليل تميزي الشخصي أو منح الآخرين فرصة للنجاح مثلي.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثامنة: العمل الجماعي"}},{"id":134,"mode":"scale","text":"عند شرح موقف أو تمثيله، أستخدم تعبيرات الوجه وحركات اليد لتجسيد الفكرة وجعلها أوضح للآخرين.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":135,"mode":"scale","text":"عندما أواجه مشكلة معقدة، أبحث عن أسبابها الجذرية قبل الاكتفاء بمعالجة آثارها المباشرة، حتى لو كان الحل المؤقت يعيد سير العمل بسرعة.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة العاشرة: حل المشكلات"}},{"id":136,"mode":"scale","text":"عندما ينشأ خلاف بين شخصين، أفهم سبب تمسّك كل منهما بموقفه، وأساعدهما على اكتشاف نقاط الاتفاق بينهما.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الاجتماعي"}},{"id":137,"mode":"scale","text":"إذا استشرفت وجود متغيرات قد تؤثر في مستقبل العمل، أبادر إلى مراجعة الخطط والاستعداد لها، حتى لو استلزم ذلك تعديل خطط معتمدة أو إعادة تخصيص بعض الموارد، قبل ظهور الحاجة الفعلية إليها، وحتى لو لم تظهر آثارها الفعلية بعد.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الأولى: المبادرة"}},{"id":138,"mode":"scale","text":"عندما أتخذ قرارًا وأنا تحت ضغط، ألاحظ ما إذا كان التوتر يؤثر في قراري، فأحاول ألا أتسرع أو أتجنب القرار بسببه.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة التاسعة: اتخاذ القرار"}},{"id":139,"mode":"scale","text":"إذا كنت مسؤولًا عن تنفيذ تغيير يؤثر في الآخرين، أتابع مدى تقبلهم له، وأدعمهم لتجاوز الصعوبات التي قد تواجههم أثناء تطبيقه، بدلًا من الاكتفاء بإلزامهم بتطبيقه.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الأولى: المبادرة"}},{"id":140,"mode":"scale","text":"عند حل مسألة أو لغز، لديّ القدرة على تتبّع المعطيات خطوةً خطوة، واكتشاف القاعدة التي تربط بينها للوصول إلى الحل.","meta":{"indicator":"الذكاءات","dimension":"الذكاء المنطقي"}},{"id":141,"mode":"scale","text":"إذا واجهت اعتراضات من أصحاب القرار على فكرة أؤمن بها، أراجعها بموضوعية، وأتقبل تعديلها إذا لزم الأمر، ثم أعيد طرحها إذا اقتنعت بأنها ما تزال تحقق مصلحة العمل بصورة أفضل.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة السادسة: التأثير والإقناع"}},{"id":142,"mode":"scale","text":"إذا كنت المسؤول عن اتخاذ قرار سيؤثر في عدة أطراف تختلف مصالحهم، وقد يسبب إشكالًا أو خلافًا بينهم، أوازن بين آثار كل خيار قبل اتخاذ القرار، بدلًا من تأجيله أو تركه ليُحسم من قبل شخص آخر.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة التاسعة: اتخاذ القرار"}},{"id":143,"mode":"scale","text":"أستطيع تحويل المعلومات والأفكار المترابطة إلى خريطة ذهنية أو مخطط بصري يوضّح العلاقات بينها ويسهّل فهمها.","meta":{"indicator":"الذكاءات","dimension":"الذكاء البصري"}},{"id":144,"mode":"scale","text":"عندما أعمل مع أشخاص يملكون خبرات أو وجهات نظر تختلف عن قناعاتي، أحرص على توظيف هذا التنوع للوصول إلى نتائج أفضل، حتى لو استلزم ذلك التخلي عن بعض أفكاري أو أسلوبي في العمل.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثامنة: العمل الجماعي"}},{"id":145,"mode":"scale","text":"إذا كان القرار سيحقق نتائج متميزة لإدارتي، لكنه قد يؤثر سلبًا في جهات أخرى أو في مصلحة العمل على المدى البعيد، أبحث عن بدائل تحقق المصلحة العامة، حتى لو أدى ذلك إلى تقليل مكاسب إدارتي.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثامنة: العمل الجماعي"}},{"id":146,"mode":"scale","text":"عندما أتعلم مهارة عملية جديدة، أفهم خطواتها وأتقنها بصورة أسرع عندما أجرّب تنفيذها بنفسي بعد مشاهدة طريقة أدائها.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الحركي"}},{"id":147,"mode":"scale","text":"إذا كنت مسؤولًا عن تطبيق تغيير جديد، وواجه في بدايته اعتراضات أو نتائج أولية غير مشجعة، أواصل تحسينه ومعالجة التحديات قبل التراجع عنه، رغم الضغوط المطالبة بالعودة إلى الطريقة السابقة.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الحادية عشرة: إدارة التغيير"}},{"id":148,"mode":"scale","text":"أستطيع التعبير عن أفكاري ومشاعري من خلال الكتابة أو الحديث بطريقة واضحة ومؤثرة.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":149,"mode":"scale","text":"إذا واجهت معارضة لفكرة أؤمن بها من أشخاص ذوي خبرة أو صلاحية أعلى، أستمع إلى ملاحظاتهم كاملة، وأطلب توضيح ما لم أتفق معه قبل أن أقدم مبرراتي أو أرد عليهم.","meta":{"indicator":"القيم","dimension":"التسامح وتقبل الآخرين"}},{"id":150,"mode":"scale","text":"عندما أسمع قراءة أو نشيدًا أو مقطعًا صوتيًا، ألاحظ بسرعة أي تغير أو خلل في النغمة أو الإيقاع.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":151,"mode":"scale","text":"عندما أشرح فكرة أو قرارًا مهمًا، لا أجد صعوبة في تعديل أسلوب شرحي وفق مستوى معرفة الأشخاص الذين أتحدث إليهم، حتى لو تطلب ذلك إعادة الشرح أو تبسيطه.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الخامسة: التواصل الفعّال"}},{"id":152,"mode":"scale","text":"عندما أواجه مشكلة، لا أكتفي بالنتائج الظاهرة، بل أفصل بين أسبابها ونتائجها وأبحث عن السبب الرئيس الذي أدى إليها قبل اختيار الحل.","meta":{"indicator":"الذكاءات","dimension":"الذكاء المنطقي"}},{"id":153,"mode":"scale","text":"عند التعامل مع المشكلات، أتبع منهجية واضحة لتحليلها واختيار الحلول المناسبة، رغم أن الحلول السريعة قد تبدو أسهل في بعض المواقف.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة العاشرة: حل المشكلات"}},{"id":154,"mode":"scale","text":"إذا تبين لي أن قرارًا اتخذته لم يعد الأنسب بعد ظهور معطيات جديدة، أبادر إلى تعديله أو التراجع عنه، حتى لو كان ذلك قد يؤثر في صورتي أمام الآخرين.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الحادية عشرة: إدارة التغيير"}},{"id":155,"mode":"scale","text":"ألاحظ غالبًا ما يشعر به الآخرون من نبرة الصوت، وتعبيرات الوجه، ولغة الجسد، حتى عندما لا يتحدثون عن مشاعرهم أو يقولون إنهم بخير.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":156,"mode":"scale","text":"عندما أعمل على تحقيق هدف أو مشروع، أراجع تقدم العمل بصورة دورية، وأعيد ترتيب الأولويات أو أسلوب التنفيذ عند الحاجة، حتى لو أدى ذلك إلى إعادة توزيع المهام أو تغيير الجدول الزمني.","meta":{"indicator":"القيم","dimension":"الرعاية والرحمة"}},{"id":157,"mode":"scale","text":"أحدد أهدافي الشخصية بناءً على معرفتي بذاتي، وما أملكه من قدرات، وما يتوافق مع اهتماماتي وطموحاتي، ومدى استعدادي للالتزام بمتطلباته.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الذاتي"}},{"id":158,"mode":"scale","text":"عندما أتحمل مسؤولية عمل أو مشروع، أعد نجاحه أو تعثره مسؤوليتي، وأتابع معالجة ما يواجهه من تحديات حتى تحقيق أهدافه، بدلًا من الاكتفاء بتفويض المهام أو متابعة سير العمل.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثانية: تحمل المسؤولية"}},{"id":159,"mode":"scale","text":"أستطيع اختصار فكرة طويلة في عنوان أو عبارة موجزة تعبّر عن معناها الأساسي.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":160,"mode":"scale","text":"عندما يضمّ المجلس قطع أثاث متعددة بأحجام مختلفة، إضافةً إلى الطاولات واللوحات والإضاءة، أستطيع تصوّر توزيعها بصورة متناسقة تحقق أفضل استفادة من المساحة.","meta":{"indicator":"الذكاءات","dimension":"الذكاء البصري"}},{"id":161,"mode":"scale","text":"بعد الاستماع إلى شرح أو مناقشة، أستطيع تذكّر الأفكار الرئيسة وتسلسلها دون الحاجة إلى قراءتها.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":162,"mode":"scale","text":"عندما ألاحظ وجود جوانب تحتاج إلى تحسين في أداء أحد أفراد الفريق، أقدم له تغذية راجعة واضحة وبنّاءة، رغم أن تجاهلها قد يجنبني أي نقاش أو إحراج.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة السابعة: تطوير الآخرين"}},{"id":163,"mode":"scale","text":"بعد إنجاز مهمة في غاية الأهمية، أستطيع تحديد الدافع الذي كان له الأثر الأكبر في استمراري؛ مثل الاستمتاع بالمهمة، أو تحقيق الإنجاز، أو الحصول على التقدير، أو تجنب اللوم.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الذاتي"}},{"id":164,"mode":"scale","text":"إذا لاحظت أن عملًا مهمًا قد يتعطل لعدم وجود من يتولى مسؤوليته، أبادر إلى تحريك العمل والتنسيق بشأنه، حتى لو لم يكن ضمن مسؤولياتي المباشرة.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الأولى: المبادرة"}},{"id":165,"mode":"scale","text":"أستطيع تحويل فكرة أو مخطط بسيط إلى شيء ملموس باستخدام الأدوات؛ مثل تنفيذ مجسّم لمبنى، أو تركيب قطع جهاز وفق مخطط، أو إصلاح عطل بسيط.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الحركي"}},{"id":166,"mode":"scale","text":"بعد سماع لحن أو إيقاع مرات قليلة، أستطيع تذكّره وترديده بصورة قريبة من النمط الذي سمعته.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الموسيقي"}},{"id":167,"mode":"scale","text":"إذا كنت أملك صلاحية اعتماد قرار استراتيجي قد يواجه معارضة من بعض المعنيين به، أحرص على بناء تأييدهم ودعمهم قبل اعتماده، بدلًا من الاعتماد على صلاحياتي لفرضه.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة السادسة: التأثير والإقناع"}},{"id":168,"mode":"scale","text":"عندما تتعدد حلول مشكلة ما، أقارن بين مزايا كل حل ونتائجه المتوقعة قبل اختيار الأكثر فاعلية.","meta":{"indicator":"الذكاءات","dimension":"الذكاء المنطقي"}},{"id":169,"mode":"scale","text":"إذا طُلب مني تقييم شخص أعرفه أو تربطني به علاقة جيدة، ألتزم بمعايير التقييم نفسها التي أطبقها على الآخرين، وأحرص على أن يكون تقييمي عادلًا وموضوعيًا، رغم أن ذلك قد لا يرضيه وقد تتأثر علاقتي به..","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الرابعة: النزاهة والموثوقية"}},{"id":170,"mode":"scale","text":"أستطيع تكوين علاقات مع أشخاص تختلف أعمارهم وشخصياتهم واهتماماتهم؛ وأجد مدخلًا مناسبًا للحديث معهم، وأعدّل أسلوبي بما يساعد على بناء علاقة جيدة.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الاجتماعي"}}],"student":[{"id":1,"mode":"binary","text":"عندما يعطيك المعلم مشروعًا جديدًا ولم يحدد لك طريقة تنفيذه، ما الذي تبدأ به غالبًا؟","options":[{"text":"أبدأ بالبحث عن المعلومات وفهم أسباب الموضوع وعلاقاته قبل أن أفكر في طريقة التنفيذ.","code":"(A التحليلي)"},{"text":"أبدأ مباشرة بوضع خطوات محددة للمشروع، وتحديد ما سأفعله أولًا وما سأفعله ثانيًا.","code":"(B التنفيذي)"}],"meta":{"indicator":"هيرمان"}},{"id":2,"mode":"binary","text":"بعد أسبوع دراسي مزدحم، وكان لدي وقت فراغ قصير، فأنا أقرب إلى:","options":[{"text":"استخدام الوقت في نشاط أحبه أو الاستمتاع به قبل العودة إلى الالتزامات.","code":"(B التنفيذي)"},{"text":"استغلال الوقت في إنهاء ما لدي من واجبات أو ترتيب أعمالي القادمة.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":3,"mode":"binary","text":"عندما نبدأ مشروعًا جماعيًا في المدرسة، فإنني أميل إلى:","options":[{"text":"المبادرة بتحديد ما نحتاج إلى إنجازه وتوجيه المجموعة للبدء سريعًا.","code":"(D الهيمنة)"},{"text":"التحدث مع زملائي ورفع حماسهم للمشاركة في المشروع.","code":"(I التأثير)"}],"meta":{"indicator":"ديسك"}},{"id":4,"mode":"binary","text":"إذا أتيحت لي فرصة المشاركة في نشاط جديد لم أجربه من قبل، فأنا أقرب إلى:","options":[{"text":"تجربته لأنني أحب اكتشاف أشياء وطرق جديدة.","code":"(D الإبداعي)"},{"text":"اختيار نشاط أعرفه وأشعر أنني أستطيع التعامل معه بثقة.","code":"(C العاطفي)"}],"meta":{"indicator":"هيرمان"}},{"id":5,"mode":"binary","text":"إذا أخبرك صديق بأنه تشاجر مع شخص آخر، ما أول شيء يلفت اهتمامك؟","options":[{"text":"معرفة ماذا حدث بالضبط، ومن بدأ المشكلة، وما الأسباب التي أدت إليها.","code":"(A التحليلي)"},{"text":"معرفة شعور صديقك تجاه ما حدث، وكيف أثّر الخلاف فيه وفي علاقته بالآخر، وما الذي أزعجه أكثر.","code":"(C العاطفي)"}],"meta":{"indicator":"هيرمان"}},{"id":6,"mode":"binary","text":"أثناء تنفيذ مشروع، اكتشفت أن الخطة الموضوعة أصبحت صعبة التطبيق، فأنا أقرب إلى:","options":[{"text":"تعديل الخطة بما يناسب الوضع الجديد حتى نستمر في العمل.","code":"(C الدقة)"},{"text":"محاولة الالتزام بالخطة الأصلية والمحافظة على خطواتها قدر الإمكان.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":7,"mode":"binary","text":"طُلب من مجموعتك تنفيذ مشروع مدرسي خلال وقت محدود، فهل:","options":[{"text":"أبدأ بنفسي في الأعمال المهمة حتى ينطلق المشروع بسرعة.","code":"المقاتل المنفرد"},{"text":"أجمع زملائي، وأوزع المهام، وأشجعهم على العمل معًا.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":8,"mode":"binary","text":"أثناء مشروع جماعي مهم، مرّ أحد أعضاء الفريق بظرف شخصي وأصبح أقل قدرة على الإنجاز، فأنا أقرب إلى:","options":[{"text":"البحث عن طريقة تحافظ على مستوى المشروع والنتيجة المطلوبة.","code":"قائد التشجيع"},{"text":"تخفيف بعض المهام عنه ومراعاة ظروفه حتى لو تأثر مستوى الإنجاز قليلًا.","code":"المقاتل المنفرد"}],"meta":{"indicator":"الدوافع"}},{"id":9,"mode":"binary","text":"عندما تبدأ دراسة موضوع لم تعرفه من قبل، ماذا تفعل غالبًا؟","options":[{"text":"أبحث عن أسبابه، وأحلل أجزائه، وأحاول فهم العلاقة بين المعلومات.","code":"(A التحليلي)"},{"text":"أبدأ في ربطه بأفكار أخرى وأتخيل أشياء جديدة يمكن أن تنتج عنه.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":10,"mode":"binary","text":"في نقاش جماعي حول فكرة مهمة، فأنا أقرب إلى:","options":[{"text":"محاولة إقناع المجموعة بالفكرة التي أراها الأفضل وجمع التأييد لها.","code":"(I التأثير)"},{"text":"إعطاء مساحة كبيرة للآراء المختلفة حتى لو لم تكن قريبة من رأيي.","code":"(D الهيمنة)"}],"meta":{"indicator":"ديسك"}},{"id":11,"mode":"binary","text":"إذا واجهت مجموعتي صعوبة مفاجئة أثناء تنفيذ نشاط، فإنني أميل إلى:","options":[{"text":"التعامل مباشرة مع المشكلة واقتراح ما يجب فعله لمواصلة العمل.","code":"(D الهيمنة)"},{"text":"المحافظة على هدوء المجموعة ومساعدتها على الاستمرار دون ارتباك.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":12,"mode":"binary","text":"عند المشاركة في مسابقة أو نشاط مدرسي، فأنا أقرب إلى:","options":[{"text":"البحث عن دور يتيح لي التميز وإظهار قدراتي والوصول إلى نتيجة عالية.","code":"(A التحليلي)"},{"text":"القيام بالدور الذي يحتاجه الفريق حتى لو كان أقل ظهورًا أمام الآخرين.","code":"(C العاطفي)"}],"meta":{"indicator":"هيرمان"}},{"id":13,"mode":"binary","text":"عندما تعمل مع مجموعة في مشروع مدرسي، ما الذي تهتم به أكثر؟","options":[{"text":"أن يعرف كل طالب مهمته، ومتى يجب أن ينتهي منها.","code":"(B التنفيذي)"},{"text":"التأكد من أن الجميع منسجمون، ويتعاونون، ويشعرون بأن لهم دورًا داخل المجموعة.","code":"(C العاطفي)"}],"meta":{"indicator":"هيرمان"}},{"id":14,"mode":"binary","text":"في الإجازة، إذا أتيحت لي فرصتان متقاربتان في المتعة، فأنا أقرب إلى:","options":[{"text":"اختيار الفرصة التي تعود عليّ بمكافأة أو فائدة شخصية أكبر.","code":"(C العاطفي)"},{"text":"اختيار الفرصة التي أستطيع من خلالها تقديم فائدة أكبر للآخرين، حتى لو كانت فائدتي الشخصية منها أقل.","code":"(B التنفيذي)"}],"meta":{"indicator":"هيرمان"}},{"id":15,"mode":"binary","text":"عندما تكون أمامي مهمة دراسية ووقتها محدود، فإنني أميل إلى:","options":[{"text":"البدء سريعًا والتركيز على الوصول إلى النتيجة المطلوبة.","code":"(D الهيمنة)"},{"text":"التأكد من فهم المطلوب وترتيب خطوات العمل قبل التنفيذ.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":16,"mode":"binary","text":"إذا طُلب منا تنفيذ نشاط بطريقة اعتاد عليها الجميع، فأنا أقرب إلى:","options":[{"text":"اقتراح طريقة أراها أنسب، حتى لو كانت مختلفة عن الطريقة المعتادة.","code":"(C الدقة)"},{"text":"الالتزام بالطريقة المعروفة إذا كانت واضحة وتحافظ على ترتيب العمل.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":17,"mode":"binary","text":"عندما تستخدم برنامجًا أو تطبيقًا جديدًا لأول مرة، ماذا تفعل غالبًا؟","options":[{"text":"أتعلم طريقة استخدامه خطوة بخطوة وألتزم بالخيارات الواضحة فيه.","code":"(B التنفيذي)"},{"text":"أجرب الأزرار والخصائص بنفسي لأكتشف طرقًا مختلفة لاستخدامه.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":18,"mode":"binary","text":"إذا كان لدي اختبار بعد عدة أيام ودعاني أصدقائي إلى نشاط ممتع، فأنا أقرب إلى:","options":[{"text":"المشاركة إذا كنت أرى أن لدي وقتًا كافيًا للدراسة لاحقًا.","code":"(B التنفيذي)"},{"text":"تأجيل المشاركة حتى أنتهي من الجزء الذي خططت لمراجعته.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":19,"mode":"binary","text":"تستعد لاختبار مهم، فأيهما أقرب لطريقتك؟","options":[{"text":"أضع لنفسي خطة مراجعة وأعتمد على جهدي للوصول إلى أفضل نتيجة.","code":"المقاتل المنفرد"},{"text":"أراجع مع زملائي، وأشجع الجميع على تبادل الشرح والاستفادة من بعضنا.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":20,"mode":"binary","text":"إذا وجدت طريقة للمذاكرة تحقق لي نتائج جيدة، فأنا أقرب إلى:","options":[{"text":"تجربة طريقة مختلفة قد تساعدني على التطور أكثر.","code":"(D الإبداعي)"},{"text":"الاستمرار بالطريقة التي أثبتت نجاحها معي.","code":"(C العاطفي)"}],"meta":{"indicator":"هيرمان"}},{"id":21,"mode":"binary","text":"عندما تسمع قصة أو تجربة مر بها شخص آخر،ما الذي يبقى في ذهنك أكثر؟","options":[{"text":"مشاعر الشخص، وما مرّ به، وكيف أثرت التجربة في علاقاته بالآخرين.","code":"(C العاطفي)"},{"text":"الأفكار والتصورات الجديدة التي تثيرها القصة في ذهنك.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":22,"mode":"binary","text":"إذا أعطاني المعلم طريقة محددة لتنفيذ مهمة، ثم وجدت طريقة أخرى أسهل، فأنا أقرب إلى:","options":[{"text":"استخدام الطريقة الأخرى إذا كانت تحقق المطلوب بشكل جيد.","code":"الأستاذ"},{"text":"تنفيذ المهمة بالطريقة المحددة حتى أتأكد أنني التزمت بالمطلوب.","code":"القناص"}],"meta":{"indicator":"الدوافع"}},{"id":23,"mode":"binary","text":"عندما أنضم إلى مجموعة من الطلاب لا أعرفهم جيدًا، فإنني غالبًا:","options":[{"text":"أبدأ الحديث معهم وأحاول تكوين جو ممتع ومريح بسرعة.","code":"(I التأثير)"},{"text":"أتعرف عليهم بهدوء وأترك العلاقة تتطور مع الوقت.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":24,"mode":"binary","text":"قبل اختبار مهم، كان لدي وقت محدود للمراجعة، وطلب مني زميل متعثر أن أساعده في فهم جزء من المادة، فأنا أقرب إلى:","options":[{"text":"إعطاء الأولوية لمراجعتي واستعدادي للاختبار؛ لأن وقتي محدود ونتيجتي مسؤولية أتحملها بنفسي.","code":"(A التحليلي)"},{"text":"تخصيص جزء من وقت المراجعة لمساعدته، حتى لو قل الوقت المتبقي لاستعدادي الشخصي.","code":"(B التنفيذي)"}],"meta":{"indicator":"هيرمان"}},{"id":25,"mode":"binary","text":"إذا أخطأت في حل مسألة عدة مرات، ماذا تفعل غالبًا؟","options":[{"text":"أبحث عن السبب الذي جعل إجابتي خاطئة، وأحاول فهم أين كان الخطأ في تفكيري.","code":"(A التحليلي)"},{"text":"أرجع إلى خطوات الحل الصحيحة وأطبقها بالترتيب حتى أصل إلى الإجابة.","code":"(B التنفيذي)"}],"meta":{"indicator":"هيرمان"}},{"id":26,"mode":"binary","text":"إذا اختلف أفراد الفريق حول طريقة تنفيذ النشاط، فأنا أقرب إلى:","options":[{"text":"توجيه النقاش نحو الخيار الذي أراه أنسب حتى يتخذ الفريق قرارًا واضحًا.","code":"(A التحليلي)"},{"text":"البحث عن طريقة تستوعب اختلاف الأعضاء وتسمح بقبول أكثر من وجهة نظر.","code":"(C العاطفي)"}],"meta":{"indicator":"هيرمان"}},{"id":27,"mode":"binary","text":"عندما أقدم عرضًا أمام الصف، فإنني أهتم أكثر بأن:","options":[{"text":"يكون العرض مشوقًا ويجذب انتباه الطلاب ويشجعهم على التفاعل.","code":"(I التأثير)"},{"text":"تكون المعلومات مرتبة وواضحة وصحيحة.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":28,"mode":"binary","text":"إذا نجح مشروع شاركت فيه نجاحًا كبيرًا، فأنا أقرب إلى:","options":[{"text":"الاهتمام بأن يعرف الآخرون مساهمتي وما قدمته لتحقيق النجاح.","code":"(C الدقة)"},{"text":"الاكتفاء بنجاح المشروع حتى لو لم يعرف معظم الناس حجم دوري فيه.","code":"(I التأثير)"}],"meta":{"indicator":"ديسك"}},{"id":29,"mode":"binary","text":"إذا اختلف أفراد مجموعتك حول قرار في مشروع مدرسي، تميل إلى:","options":[{"text":"مقارنة الآراء واختيار الرأي الأقوى من حيث الأسباب والنتائج.","code":"(A التحليلي)"},{"text":"الاستماع للجميع والبحث عن قرار يمكن أن يتقبله أعضاء المجموعة ويحافظ على تعاونهم.","code":"(C العاطفي)"}],"meta":{"indicator":"هيرمان"}},{"id":30,"mode":"binary","text":"إذا كان لدي شيء جيد لم أعد أستخدمه كثيرًا وكان أحد أصدقائي يحتاج إليه، فأنا أقرب إلى:","options":[{"text":"الاحتفاظ به لأنني قد أحتاج إليه مرة أخرى في المستقبل.","code":"(C العاطفي)"},{"text":"إعطائه له إذا كنت أرى أنه سينتفع به أكثر مني الآن.","code":"(A التحليلي)"}],"meta":{"indicator":"هيرمان"}},{"id":31,"mode":"binary","text":"حدثت مشكلة أثناء نشاط جماعي، فماذا تفعل غالبًا؟","options":[{"text":"أتدخل مباشرة وأحاول معالجة المشكلة حتى يعود النشاط إلى مساره.","code":"المقاتل المنفرد"},{"text":"أجمع المشاركين وأحفزهم للوصول إلى حل وتنفيذه معًا.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":32,"mode":"binary","text":"عندما أختار كيف أتصرف في موقف لا توجد فيه تعليمات واضحة، فأنا أقرب إلى:","options":[{"text":"الاعتماد على قناعتي الشخصية واتخاذ القرار الذي أراه مناسبًا.","code":"قائد التشجيع"},{"text":"الرجوع إلى ما اعتدنا عليه من قواعد وعادات قبل اتخاذ القرار.","code":"المقاتل المنفرد"}],"meta":{"indicator":"الدوافع"}},{"id":33,"mode":"binary","text":"عندما تفكر في مشروع أو نشاط جديد، ما الذي يشد اهتمامك أكثر؟","options":[{"text":"ما يمكن أن ينجح الآن وفق المعلومات المتوفرة والنتائج التي يمكن توقعها.","code":"(I التأثير)"},{"text":"كيف يمكن أن يتطور المشروع في المستقبل، وما الفرص الجديدة التي قد تظهر بسببه.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":34,"mode":"binary","text":"بعد الانتهاء من اختبار أو مشروع بذلت فيه جهدًا كبيرًا، فأنا أقرب إلى:","options":[{"text":"تخصيص وقت للاحتفال أو القيام بشيء أستمتع به قبل التفكير في المهمة التالية.","code":"(C الدقة)"},{"text":"البدء في ترتيب المهمة أو الهدف التالي إذا كان لدي شيء مهم ينتظرني.","code":"(I التأثير)"}],"meta":{"indicator":"ديسك"}},{"id":35,"mode":"binary","text":"إذا تغيرت طريقة تنفيذ مشروع دراسي بعد أن بدأنا فيه، فإنني أميل إلى:","options":[{"text":"مساعدة زملائي على التكيف مع التغيير والمحافظة على هدوء المجموعة.","code":"(S الثبات)"},{"text":"فهم التعليمات الجديدة بدقة والتأكد من تطبيقها بشكل صحيح.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":36,"mode":"binary","text":"إذا أتيحت لي فرصة الانضمام إلى مجموعة طلابية جديدة لا أعرف معظم أعضائها، فأنا أقرب إلى:","options":[{"text":"الانضمام إليها لأنها تتيح لي تجربة مختلفة والتعرف على أفكار وأشخاص جدد.","code":"(D الإبداعي)"},{"text":"اختيار مجموعة أعرف أفرادها وأشعر بالراحة في العمل معهم.","code":"(C العاطفي)"}],"meta":{"indicator":"هيرمان"}},{"id":37,"mode":"binary","text":"إذا انضم طالب جديد إلى مجموعتك أثناء تنفيذ مهمة، ماذا تفعل أولًا؟","options":[{"text":"أوضح له دوره، وما المطلوب منه، والخطوات التي يجب أن يتبعها.","code":"(B التنفيذي)"},{"text":"أتعرف إليه وأساعده على الشعور بالراحة مع أفراد المجموعة.","code":"(C العاطفي)"}],"meta":{"indicator":"هيرمان"}},{"id":38,"mode":"binary","text":"إذا تغير برنامجي الدراسي فجأة بسبب أمر لم أكن أتوقعه، فأنا أقرب إلى:","options":[{"text":"إعادة ترتيب وقتي وأولوياتي بما يناسب الظروف الجديدة.","code":"(D الهيمنة)"},{"text":"محاولة المحافظة على برنامجي وترتيبه الأصلي قدر الإمكان.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":39,"mode":"binary","text":"عندما تختلف آراء مجموعتي حول الطريقة الأفضل لإنجاز المهمة، فإنني أميل إلى:","options":[{"text":"توجيه النقاش نحو اختيار قرار واضح حتى نتمكن من مواصلة العمل.","code":"(D الهيمنة)"},{"text":"مناقشة زملائي وشرح الفكرة التي أراها مناسبة بطريقة تشجعهم على الاقتناع بها ودعمها.","code":"(I التأثير)"}],"meta":{"indicator":"ديسك"}},{"id":40,"mode":"binary","text":"عندما يساعدني زميل في مهمة لكنه ينجزها بمستوى أقل مما أتوقع، فأنا أقرب إلى:","options":[{"text":"طلب تحسين العمل حتى يصل إلى المستوى الذي يحتاجه المشروع.","code":"القناص"},{"text":"تقدير جهده ومساعدته بهدوء دون الضغط عليه أكثر من قدرته.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":41,"mode":"binary","text":"عندما تخطط مجموعتك لمشروع يستمر عدة أشهر، ما الذي تهتم به أكثر؟","options":[{"text":"تحديد الخطوات والمواعيد والمسؤوليات حتى يسير العمل بانتظام.","code":"الأستاذ"},{"text":"تصور الاتجاه الذي يمكن أن يصل إليه المشروع مستقبلًا، وما الفرص الجديدة التي يمكن تطويرها أثناء الطريق.","code":"القناص"}],"meta":{"indicator":"الدوافع"}},{"id":42,"mode":"binary","text":"عندما يكون لدي اقتراح أراه مهمًا للمدرسة أو الفريق، فأنا أقرب إلى:","options":[{"text":"التواصل مع الأشخاص المؤثرين ومحاولة الحصول على دعمهم لتنفيذه.","code":"(S الثبات)"},{"text":"عرضه والاستماع إلى الآراء المختلفة حوله، حتى لو أدى ذلك إلى تعديله بصورة كبيرة.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":43,"mode":"binary","text":"شاركت في منافسة جماعية، فأيهما يمنحك حماسًا أكبر؟","options":[{"text":"أن يكون لي دور أعتمد فيه على أدائي الشخصي لتحقيق نتيجة قوية.","code":"المقاتل المنفرد"},{"text":"أن أحفز المجموعة وأساعدها على العمل بروح واحدة لتحقيق الفوز.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":44,"mode":"binary","text":"إذا كانت مجموعتك ستقدم عرضًا أمام الطلاب، ما الجانب الذي تهتم به أكثر؟","options":[{"text":"أن يشعر الحضور بأن العرض قريب منهم، وأن يتفاعلوا معه ويشاركوا أثناءه.","code":"(C العاطفي)"},{"text":"أن تكون طريقة العرض مبتكرة وغير معتادة، وتقدم الفكرة بأسلوب لم يشاهدوه من قبل.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":45,"mode":"binary","text":"إذا أتيحت لي فرصة أن أكون قائدًا لفريق أو عضوًا يساعد في التنفيذ، فأنا أقرب إلى:","options":[{"text":"اختيار القيادة لأنها تمنحني مسؤولية أكبر وفرصة لإثبات قدراتي.","code":"(A التحليلي)"},{"text":"اختيار الدور الذي أستطيع من خلاله خدمة الفريق بشكل أفضل، سواء كنت قائدًا أو عضوًا.","code":"(B التنفيذي)"}],"meta":{"indicator":"هيرمان"}},{"id":46,"mode":"binary","text":"عندما يتأخر بعض زملائي في إنجاز الجزء المطلوب منهم، فإنني أميل إلى:","options":[{"text":"تنبيههم إلى التأخير وحثهم على الإسراع حتى ننجز المهمة في الوقت المطلوب.","code":"(D الهيمنة)"},{"text":"معرفة سبب التأخير ومساعدتهم بهدوء حتى يتمكنوا من إكمال الجزء المطلوب منهم.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":47,"mode":"binary","text":"عندما أفكر في مكافأة أحصل عليها بعد إنجاز مهم، فأنا أقرب إلى:","options":[{"text":"تفضيل مكافأة مادية أو شيء أستطيع امتلاكه والاستفادة منه.","code":"قائد التشجيع"},{"text":"تفضيل استخدام جزء من المكافأة في إسعاد شخص آخر أو تقديم شيء مفيد له.","code":"المقاتل المنفرد"}],"meta":{"indicator":"الدوافع"}},{"id":48,"mode":"binary","text":"إذا كان لديك اختبار بعد عدة أيام، ما الذي يشغل اهتمامك أكثر؟","options":[{"text":"أفهم الأفكار الصعبة وأبحث عن سبب عدم وضوحها، وربط المعلومات ببعضها حتى تتضح لي الصورة.","code":"(A التحليلي)"},{"text":"أضع جدولًا واضحًا للمذاكرة، وأحدد ما سأراجعه في كل يوم وألتزم به.","code":"(B التنفيذي)"}],"meta":{"indicator":"هيرمان"}},{"id":49,"mode":"binary","text":"عندما يكون لدي رأي مختلف عن الرأي المعتاد في موضوع مهم، فأنا أقرب إلى:","options":[{"text":"التعبير عن الرأي الذي أقتنع به، حتى لو كان مختلفًا عما اعتاده من حولي.","code":"المقاتل المنفرد"},{"text":"مراعاة القيم والقواعد التي تربيت عليها قبل تبني رأي مختلف عنها.","code":"قائد التشجيع"}],"meta":{"indicator":"الدوافع"}},{"id":50,"mode":"binary","text":"إذا كان لدي واجب دراسي مهم، فإنني أميل إلى:","options":[{"text":"التركيز على إنجاز الواجب والوصول إلى النتيجة المطلوبة، وتغيير طريقتي إذا وجدت طريقة أسرع لإنجازه.","code":"(D الهيمنة)"},{"text":"اتباع خطوات واضحة في إنجازه، ثم مراجعة ما كتبت للتأكد من صحته وعدم وجود أخطاء.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":51,"mode":"binary","text":"طُلب من مجموعتك إعداد عرض مهم أمام الطلاب، فماذا تفضل؟","options":[{"text":"أتولى الأجزاء التي تحتاج إلى أعلى مستوى من الدقة حتى أضمن جودتها بنفسي.","code":"القناص"},{"text":"أوزع الأجزاء على زملائي، وأساعدهم حتى يخرج العرض بالمستوى المطلوب.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":52,"mode":"binary","text":"إذا قرأت خبرًا أثار نقاشًا بين الطلاب، ما الذي يهمك أكثر؟","options":[{"text":"التحقق من صحة الخبر، ومقارنة المعلومات والأدلة قبل تكوين رأيي.","code":"(C العاطفي)"},{"text":"معرفة كيف تلقّى الناس الخبر، وما المشاعر التي أثارها لديهم.","code":"(A التحليلي)"}],"meta":{"indicator":"هيرمان"}},{"id":53,"mode":"binary","text":"في الأنشطة والرحلات المدرسية، فإنني غالبًا:","options":[{"text":"أستمتع بالتحدث مع عدد كبير من الطلاب والمشاركة في الأجواء والحماس.","code":"(I التأثير)"},{"text":"أفضل قضاء الوقت مع الطلاب الذين أعرفهم جيدًا وأشعر معهم براحة أكبر.","code":"(S الثبات)"}],"meta":{"indicator":"ديسك"}},{"id":54,"mode":"binary","text":"تعلمت مهارة جديدة يحتاجها زملاؤك في مشروع دراسي، فهل:","options":[{"text":"أستخدمها بنفسي في الأجزاء المهمة التي تتطلب إتقانًا عاليًا.","code":"القناص"},{"text":"أشرحها لزملائي وأتابع تطبيقهم حتى يتمكنوا منها بأنفسهم.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":55,"mode":"binary","text":"إذا عرض عليك المعلم نتائج استطلاع أجراه الصف، ما الذي يلفت انتباهك أكثر؟","options":[{"text":"مقارنة الأرقام والنتائج، ومحاولة معرفة ما الذي تعنيه وما العلاقة بينها.","code":"(C الدقة)"},{"text":"التفكير في أفكار جديدة يمكن تنفيذها بناءً على ما أظهرته النتائج.","code":"(I التأثير)"}],"meta":{"indicator":"ديسك"}},{"id":56,"mode":"binary","text":"عندما نناقش فكرة لمشروع أو نشاط جديد، فإنني أميل إلى:","options":[{"text":"عرض الفكرة بطريقة مشوقة تشجع زملائي على الحماس لها والمشاركة فيها.","code":"(I التأثير)"},{"text":"التفكير في تفاصيل الفكرة ومتطلباتها، والتأكد من إمكانية تنفيذها بشكل صحيح.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":57,"mode":"binary","text":"لاحظت أن مجموعتك تكرر الخطأ نفسه في أحد الأعمال، فهل:","options":[{"text":"أراجع العمل بنفسي وأصحح الأخطاء حتى يصبح دقيقًا.","code":"القناص"},{"text":"أوضح لزملائي سبب الأخطاء وأساعدهم على تجنبها في المرات القادمة.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":58,"mode":"binary","text":"إذا شاركت في تنظيم فعالية مدرسية، ما الذي تفكر فيه أكثر؟","options":[{"text":"ترتيب البرنامج والتجهيزات والمواعيد، والتأكد من سير الفعالية وفق الخطة.","code":"(B التنفيذي)"},{"text":"أن يشعر المشاركون بالراحة والحماس، وأن يتفاعلوا مع الفعالية ويستمتعوا بها.","code":"(C العاطفي)"}],"meta":{"indicator":"هيرمان"}},{"id":59,"mode":"binary","text":"عندما أعمل على واجب أو مشروع يحتاج إلى عدة أيام، فإنني أميل إلى:","options":[{"text":"الاستمرار في العمل عليه بهدوء وبشكل ثابت حتى أنتهي منه، دون أن أهتم كثيرًا بتقسيمه إلى أجزاء محددة.","code":"(S الثبات)"},{"text":"تقسيمه إلى أجزاء واضحة، ومراجعة كل جزء للتأكد من اكتماله بالشكل المطلوب.","code":"(C الدقة)"}],"meta":{"indicator":"ديسك"}},{"id":60,"mode":"binary","text":"عندما تعمل مجموعتك على مهمة في غاية الأهمية، فأيهما يرضيك أكثر؟","options":[{"text":"أن أُنجز جزءًا صعبًا بدقة عالية حتى يخرج العمل بالمستوى الذي أريده.","code":"القناص"},{"text":"أن أساعد زملائي على تحسين أدائهم حتى يصبحوا قادرين على إنجاز العمل بشكل أفضل.","code":"الأستاذ"}],"meta":{"indicator":"الدوافع"}},{"id":61,"mode":"binary","text":"إذا طُلب من مجموعتك تنفيذ نشاط مدرسي يتكرر كل عام، ماذا تفضل؟","options":[{"text":"استخدام الطريقة السابقة مع تحسين التنظيم والخطوات، ليصبح أسهل في التنفيذ.","code":"(B التنفيذي)"},{"text":"تغيير فكرة النشاط أو طريقته وتجربة شكل جديد تمامًا.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":62,"mode":"binary","text":"إذا أخبرك صديق بأنه ملّ من الدراسة، ماذا تميل إلى فعله؟","options":[{"text":"أستمع إليه وأحاول فهم شعوره وما الذي يزعجه، ثم أسانده بالطريقة التي تناسبه.","code":"(C العاطفي)"},{"text":"أفكر معه في طريقة جديدة ومختلفة للمذاكرة، وأقترح أسلوبًا لم يجرّبه من قبل.","code":"(D الإبداعي)"}],"meta":{"indicator":"هيرمان"}},{"id":63,"mode":"rank","text":"عند المشاركة في معرض علمي أو تقني، رتّب المهام التالية بحسب ما تستمتع به أكثر:","options":[{"text":"تركيب الأجهزة والتجهيزات وتجربتها عمليًا.","code":"R"},{"text":"استقبال الزوار ومساعدتهم وشرح المعروضات لهم.","code":"S"},{"text":"البحث عن المعلومات المتعلقة بالمعروضات والتأكد من صحتها.","code":"I"},{"text":"تصميم شكل المعرض ومحتواه بطريقة مبتكرة.","code":"A"}],"meta":{"indicator":"هولاند"}},{"id":64,"mode":"rank","text":"تعطّل جهاز مهم في المنزل، وبدأ أفراد الأسرة في مناقشة أفضل طريقة للتعامل معه، رتّب ما تفضله أكثر:","options":[{"text":"البحث عن سبب العطل وتحليل الاحتمالات لمعرفة المشكلة بدقة.","code":"I"},{"text":"طرح الحل الذي أراه مناسبًا ومحاولة إقناع الآخرين باعتماده.","code":"E"},{"text":"فحص الجهاز وتجربة إصلاحه أو إعادة تركيب أجزائه بنفسي.","code":"R"},{"text":"التفكير في طريقة مختلفة أو مبتكرة لحل المشكلة أو الاستفادة من الجهاز.","code":"A"}],"meta":{"indicator":"هولاند"}},{"id":65,"mode":"rank","text":"إذا قررت صنع هدية أو قطعة بسيطة لشخص قريب منك، رتّب ما تستمتع به أكثر:","options":[{"text":"ابتكار شكل مميز للهدية وإضافة لمسات خاصة عليها.","code":"A"},{"text":"ترتيب خطوات العمل والمواد المطلوبة قبل البدء.","code":"C"},{"text":"استخدام الأدوات وصنع القطعة بيدي.","code":"R"},{"text":"البحث عن أفضل المواد والطرق المناسبة لصنعها.","code":"I"}],"meta":{"indicator":"هولاند"}},{"id":66,"mode":"rank","text":"قررت مع مجموعة من الأصدقاء تنفيذ فكرة مفيدة في الحي، رتّب ما تفضله أكثر:","options":[{"text":"تجهيز ما يحتاجه العمل وتنفيذ الجوانب العملية بنفسي.","code":"R"},{"text":"مساعدة أفراد المجموعة وتشجيعهم أثناء التنفيذ.","code":"S"},{"text":"دراسة المشكلة والبحث عن أفضل طريقة لمعالجتها.","code":"I"},{"text":"عرض الفكرة على الآخرين ومحاولة كسب دعمهم لها.","code":"E"}],"meta":{"indicator":"هولاند"}},{"id":67,"mode":"rank","text":"إذا فكرت مجموعة من أصدقائك في إطلاق مشروع صغير، رتّب الأدوار التالية بحسب ما تفضله:","options":[{"text":"دراسة الفكرة والسوق وجمع المعلومات لمعرفة فرص نجاحها.","code":"I"},{"text":"قيادة المشروع والتفاوض مع الآخرين والترويج له.","code":"E"},{"text":"تجهيز المنتج أو تنفيذ الأعمال العملية المتعلقة به.","code":"R"},{"text":"التعامل مع العملاء وفهم احتياجاتهم ومساعدتهم.","code":"S"}],"meta":{"indicator":"هولاند"}},{"id":68,"mode":"rank","text":"عند تنظيم مناسبة عائلية كبيرة، رتّب المهام التالية بحسب ما تستمتع به أكثر:","options":[{"text":"ابتكار أفكار جديدة للأنشطة أو طريقة تقديم المناسبة.","code":"A"},{"text":"إعداد البرنامج والمواعيد والقوائم وتنظيم التفاصيل.","code":"C"},{"text":"تجهيز المكان ونقل الأدوات وتركيب ما يحتاج إلى تجهيز.","code":"R"},{"text":"استقبال الضيوف والاهتمام بهم ومساعدتهم.","code":"S"}],"meta":{"indicator":"هولاند"}},{"id":69,"mode":"rank","text":"إذا أردتم إعادة ترتيب غرفة أو مجلس في المنزل، رتّب ما تستمتع به أكثر:","options":[{"text":"تحريك الأثاث وتجهيز المكان وتنفيذ التغييرات عمليًا.","code":"R"},{"text":"الاستماع إلى احتياجات أفراد الأسرة ومساعدتهم على اختيار ترتيب يناسبهم.","code":"S"},{"text":"دراسة المساحة ومقارنة الخيارات لمعرفة أفضل توزيع ممكن.","code":"I"},{"text":"وضع قائمة بما يحتاج إلى نقل أو شراء وترتيب خطوات التنفيذ.","code":"C"}],"meta":{"indicator":"هولاند"}},{"id":70,"mode":"rank","text":"عندما تشارك مع أفراد الأسرة في اختيار جهاز إلكتروني جديد للمنزل، رتّب ما تفضله أكثر:","options":[{"text":"البحث عن كيفية عمل الجهاز، وفهم الفروق التقنية بين الخيارات قبل الاختيار.","code":"I"},{"text":"مناقشة الخيارات مع الآخرين ومحاولة التأثير في القرار نحو الخيار الذي أراه أفضل.","code":"E"},{"text":"تجربة الأجهزة بنفسي والتعامل معها عمليًا قبل اتخاذ القرار.","code":"R"},{"text":"ترتيب الأسعار والمواصفات والخيارات في قائمة واضحة تساعدني على المتابعة والاختيار.","code":"C"}],"meta":{"indicator":"هولاند"}},{"id":71,"mode":"rank","text":"إذا أردت مع أصدقائك إنشاء محتوى أو مشروع على الإنترنت، رتّب ما تستمتع به أكثر:","options":[{"text":"تصميم شكل المحتوى وطريقة تقديمه بأسلوب مبتكر.","code":"A"},{"text":"تنظيم خطة النشر والمهام ومتابعة تنفيذها.","code":"C"},{"text":"تجهيز المعدات أو تنفيذ الجانب التقني والعملي.","code":"R"},{"text":"قيادة المجموعة والترويج للمشروع وجذب المتابعين.","code":"E"}],"meta":{"indicator":"هولاند"}},{"id":72,"mode":"rank","text":"عند المشاركة في نشاط تطوعي لخدمة الحي، رتّب الأدوار التالية بحسب ما تستمتع به أكثر:","options":[{"text":"تنفيذ الأعمال الميدانية والتجهيزات المطلوبة.","code":"R"},{"text":"التعامل مع المستفيدين ومساعدتهم وتقديم الدعم لهم.","code":"S"},{"text":"ابتكار أفكار أو وسائل جديدة تجعل النشاط أكثر جاذبية.","code":"A"},{"text":"قيادة المجموعة وتوزيع الأدوار وتشجيع الآخرين على المشاركة.","code":"E"}],"meta":{"indicator":"هولاند"}},{"id":73,"mode":"rank","text":"إذا أردت تقديم فكرة أو موضوع يهمك لمجموعة من الناس، رتّب ما تستمتع به أكثر:","options":[{"text":"البحث في الموضوع وجمع المعلومات والتأكد من دقتها.","code":"I"},{"text":"التحدث أمام الآخرين وإقناعهم بالفكرة.","code":"E"},{"text":"ابتكار طريقة مميزة ومختلفة لعرض الفكرة.","code":"A"},{"text":"تبسيط الفكرة للآخرين ومساعدتهم على فهمها.","code":"S"}],"meta":{"indicator":"هولاند"}},{"id":74,"mode":"rank","text":"إذا أنشأت حسابًا أو قناة تهتم بموضوع تحبه، رتّب المهام التالية:","options":[{"text":"كتابة المحتوى أو تصويره وتصميمه بأسلوبي الخاص.","code":"A"},{"text":"ترتيب الموضوعات ومواعيد النشر ومتابعة ما تم نشره.","code":"C"},{"text":"البحث عن المعلومات والتحقق منها قبل استخدامها.","code":"I"},{"text":"التواصل مع المتابعين والاستماع إلى آرائهم والإجابة عنهم.","code":"S"}],"meta":{"indicator":"هولاند"}},{"id":75,"mode":"rank","text":"عند تجهيز مكان لقضاء يوم عائلي أو لقاء مع الأصدقاء، رتّب ما تستمتع به أكثر:","options":[{"text":"تجهيز المكان والأدوات وترتيبها عمليًا.","code":"R"},{"text":"استقبال الأشخاص والاهتمام باحتياجاتهم أثناء اللقاء.","code":"S"},{"text":"ابتكار شكل جميل أو فكرة مختلفة للمكان والأنشطة.","code":"A"},{"text":"إعداد قائمة بالاحتياجات وتنظيم الوقت والتجهيزات.","code":"C"}],"meta":{"indicator":"هولاند"}},{"id":76,"mode":"rank","text":"إذا فكرت في تحويل هواية تحبها إلى مشروع صغير، رتّب ما يثير اهتمامك أكثر:","options":[{"text":"دراسة الفكرة ومعرفة مدى نجاحها والطلب عليها.","code":"I"},{"text":"قيادة المشروع والترويج له والتفاوض مع العملاء.","code":"E"},{"text":"ابتكار اسم أو هوية أو طريقة مميزة لتقديم المشروع.","code":"A"},{"text":"إعداد خطة واضحة للطلبات والمواعيد والمصروفات ومتابعتها.","code":"C"}],"meta":{"indicator":"هولاند"}},{"id":77,"mode":"rank","text":"إذا قررت الأسرة تطوير مساحة في المنزل لتصبح أكثر فائدة وراحة، رتّب المهام التالية بحسب ما تستمتع به أكثر:","options":[{"text":"تخيّل شكل جديد للمكان واقتراح أفكار غير تقليدية لتصميمه أو استخدامه.","code":"A"},{"text":"ترتيب خطوات التغيير وتحديد ما يجب إنجازه أولًا ثم ما يليه.","code":"C"},{"text":"ملاحظة المشكلات الموجودة في المكان وتحليل أسبابها قبل اقتراح الحل.","code":"I"},{"text":"عرض المقترحات على أفراد الأسرة ومحاولة كسب تأييدهم للفكرة التي أراها أفضل.","code":"E"}],"meta":{"indicator":"هولاند"}},{"id":78,"mode":"rank","text":"عند التخطيط لرحلة مع مجموعة من الأصدقاء أو الأسرة، رتّب ما تفضله أكثر:","options":[{"text":"تجهيز الأدوات والاحتياجات والمشاركة في الأعمال العملية أثناء الرحلة.","code":"R"},{"text":"الاهتمام بأفراد المجموعة ومساعدتهم والتأكد من راحتهم.","code":"S"},{"text":"قيادة المجموعة واتخاذ القرارات عند اختلاف الآراء.","code":"E"},{"text":"إعداد الجدول والمواعيد وقائمة الاحتياجات وتنظيم تفاصيل الرحلة.","code":"C"}],"meta":{"indicator":"هولاند"}},{"id":79,"mode":"rank","text":"إذا أرادت مجموعة من الشباب نشر الوعي حول قضية مجتمعية، رتّب ما تفضله أكثر:","options":[{"text":"البحث عن المعلومات والأدلة لفهم القضية بصورة دقيقة.","code":"I"},{"text":"التحدث مع الناس ومحاولة إقناعهم بأهمية القضية.","code":"E"},{"text":"الاستماع إلى من يواجهون المشكلة ومساعدتهم ودعمهم.","code":"S"},{"text":"تنظيم المواعيد والمهام والقوائم ومتابعة تنفيذ الحملة.","code":"C"}],"meta":{"indicator":"هولاند"}},{"id":80,"mode":"rank","text":"عند المشاركة في نادٍ طلابي، رتّب المهام التالية بحسب ما تستمتع به أكثر:","options":[{"text":"ابتكار أنشطة ومحتوى جديد للنادي.","code":"A"},{"text":"إعداد الجداول والقوائم وتنظيم الاجتماعات والمهام.","code":"C"},{"text":"تعليم أعضاء النادي مهارات جديدة ومساعدتهم على تطوير قدراتهم.","code":"S"},{"text":"الترويج للنادي والتفاوض لجذب دعم أو مشاركين جدد.","code":"E"}],"meta":{"indicator":"هولاند"}},{"id":81,"mode":"scale","text":"أستمتع بقراءة القصص والمقالات، وأنتبه إلى معاني الكلمات وطريقة صياغة الأفكار، ثم أعبّر عما فهمته بأسلوبي.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":82,"mode":"scale","text":"عندما يكون لدي أكثر من اختبار أو واجب في الفترة نفسها، أحدد ما يحتاج إلى وقت أكبر وأرتب أولوياتي قبل البدء.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثالثة: التخطيط والتنظيم"}},{"id":83,"mode":"scale","text":"عندما أبدأ المذاكرة أو إنجاز واجب، أستطيع الاستمرار فيه رغم وجود الهاتف أو الألعاب أو أشياء أخرى أفضل القيام بها في ذلك الوقت.","meta":{"indicator":"القيم","dimension":"الانضباط والالتزام"}},{"id":84,"mode":"scale","text":"عندما أراجع أرقامًا أو بيانات متعددة، أستطيع حساب الفروق والنسب بينها، وملاحظة الأنماط واتجاهات الزيادة أو الانخفاض؛ للوصول إلى نتيجة واضحة.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الرياضي"}},{"id":85,"mode":"scale","text":"إذا أخفقت في تنفيذ جزء من مشروع جماعي كنت مسؤولًا عنه، أتحمل مسؤوليتي وأعمل على معالجة التقصير بدلًا من الاكتفاء بتقديم المبررات.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثانية: تحمل المسؤولية"}},{"id":86,"mode":"scale","text":"إذا لم أفهم موضوعًا في الدرس، أبحث عن شرح آخر أو مصدر يساعدني على فهمه بدلًا من انتظار أن يعاد شرحه لي فقط.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثانية: التعلم والتطوير"}},{"id":87,"mode":"scale","text":"عندما أواجه مشكلة في الدراسة أو مشروع، أحاول أولًا تحديد السبب الحقيقي للمشكلة قبل اختيار الحل.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة العاشرة: حل المشكلات"}},{"id":88,"mode":"scale","text":"أفهم الخرائط والمخططات بسهولة، وأستطيع استخدامها لتحديد المواقع والاتجاهات أو الوصول إلى مكان لم أزره من قبل.","meta":{"indicator":"الذكاءات","dimension":"الذكاء البصري"}},{"id":89,"mode":"scale","text":"عندما أشرح فكرة لزملائي، أغيّر طريقة الشرح أو أعطي مثالًا آخر إذا لاحظت أنهم لم يفهموا ما أقصده.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الخامسة: التواصل الفعّال"}},{"id":90,"mode":"scale","text":"أميل إلى الأنشطة التي تتطلب الحركة والتطبيق واستخدام الأدوات؛ مثل الرياضة، أو الصيانة، أو الأعمال الميدانية، أكثر من الاكتفاء بالجلوس والاستماع.","meta":{"indicator":"الذكاءات","dimension":"الذكاء السمعي"}},{"id":91,"mode":"scale","text":"عندما أعمل ضمن مجموعة، أنجز الجزء المسؤول عنه وأساعد في المهام المشتركة إذا احتاج الفريق إلى ذلك.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثانية: تحمل المسؤولية"}},{"id":92,"mode":"scale","text":"في العمل الجماعي، ألاحظ ما يجيده كل فرد وما يناسبه من أدوار، وأعرف من يحتاج إلى توضيح أو تشجيع حتى يعمل الفريق بفاعلية.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الأولى: المبادرة"}},{"id":93,"mode":"scale","text":"إذا تغيرت خطة كنت مستعدًا لها، أستطيع إعادة ترتيب ما سأفعله والتعامل مع الوضع الجديد بدلًا من أن يعطلني التغيير لفترة طويلة.","meta":{"indicator":"القيم","dimension":"المرونة والتكيف"}},{"id":94,"mode":"scale","text":"أعرف المهام التي أتميز فيها والمهام التي تحتاج مني إلى تطوير أو مساعدة، وأراعي ذلك عند تحمّل المسؤوليات.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الذاتي"}},{"id":95,"mode":"scale","text":"إذا حددت لنفسي وقتًا للبدء في مهمة أو مذاكرة، ألتزم به حتى عندما لا يكون هناك من يتابعني أو يذكرني.","meta":{"indicator":"القيم","dimension":"الانضباط والالتزام"}},{"id":96,"mode":"scale","text":"أتذكر الكلمات والمعلومات بصورة أفضل عندما أسمعها بصوت واضح أو أربطها بلحن أو إيقاع معين.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":97,"mode":"scale","text":"إذا كان لدي اختبار مهم بعد عدة أيام، أوزع المراجعة بشكل مجدول بدلًا من الاعتماد غالبًا على المذاكرة في اليوم الأخير.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثالثة: التخطيط والتنظيم"}},{"id":98,"mode":"scale","text":"عندما أناقش موضوعًا، أستطيع اختيار الكلمات والأمثلة والحجج التي تعبّر عن فكرتي بدقة وتدعمها بوضوح.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":99,"mode":"scale","text":"إذا ارتكبت خطأ أدى إلى نتيجة غير جيدة، أراجع ما كان بإمكاني فعله بصورة أفضل حتى لو كانت هناك ظروف أخرى ساهمت في المشكلة.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثانية: تحمل المسؤولية"}},{"id":100,"mode":"scale","text":"أميل إلى المسائل والألعاب التي تتطلب اكتشاف قاعدة خفية أو اتباع سلسلة من الاستنتاجات للوصول إلى الحل.","meta":{"indicator":"الذكاءات","dimension":"الذكاء المنطقي"}},{"id":101,"mode":"scale","text":"عندما يثير موضوع دراسي اهتمامي، أبحث عنه خارج ما هو مطلوب في الكتاب أو الواجب لأعرف عنه بصورة أوسع.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":102,"mode":"scale","text":"أستطيع تكوين صورة ذهنية واضحة للشكل النهائي قبل تنفيذه؛ مثل تصميم شعار، أو إعداد عرض مرئي، أو ابتكار شكل منتج.","meta":{"indicator":"الذكاءات","dimension":"الذكاء البصري"}},{"id":103,"mode":"scale","text":"إذا كان أمامي أكثر من خيار مهم، أقارن بين مزايا كل خيار ونتائجه المحتملة قبل أن أقرر أيها أنسب.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة التاسعة: اتخاذ القرار"}},{"id":104,"mode":"scale","text":"أستطيع التعبير عن الأفكار والمشاعر من خلال الأداء الجسدي؛ مثل التمثيل، أو الإلقاء المصحوب بالإشارات، أو تقليد حركة لشرح موقف.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":105,"mode":"scale","text":"عندما يتحدث شخص معي في موضوع أختلف معه فيه، أستمع إلى وجهة نظره كاملة قبل أن أبدأ في الرد عليها.","meta":{"indicator":"القيم","dimension":"التسامح وتقبل الآخرين"}},{"id":106,"mode":"scale","text":"ألاحظ غالبًا ما يشعر به الآخرون من نبرة الصوت، وتعبيرات الوجه، ولغة الجسد، حتى عندما لا يتحدثون عن مشاعرهم.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":107,"mode":"scale","text":"إذا اختلفت طريقة أحد زملائي عن طريقتي في تنفيذ المهمة، أحاول الاستفادة من فكرته إذا كانت تساعد الفريق على الوصول إلى نتيجة أفضل.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثامنة: العمل الجماعي"}},{"id":108,"mode":"scale","text":"أستطيع التحكم في مشاعري في المواقف الضاغطة أو المحزنة أو المفرحة، والمحافظة على اتزاني قبل اتخاذ القرار أو التصرف.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الذاتي"}},{"id":109,"mode":"scale","text":"إذا حصلت على نتيجة أقل مما كنت أتوقع في اختبار أو مهمة، أراجع أسبابها وأعدل طريقتي في المرة التالية بدلًا من فقدان الحماس.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثانية: التعلم والتطوير"}},{"id":110,"mode":"scale","text":"عندما أسمع قراءة أو نشيدًا أو مقطعًا صوتيًا، ألاحظ بسرعة أي تغير أو خلل في النغمة أو الإيقاع.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":111,"mode":"scale","text":"عندما أشعر بالملل أو انخفاض الحماس أثناء مهمة مهمة، أواصل العمل عليها أو أعود إليها بعد فترة قصيرة بدلًا من تركها دون إكمال.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثانية: تحمل المسؤولية"}},{"id":112,"mode":"scale","text":"أستطيع التعبير عن أفكاري ومشاعري من خلال الكتابة أو الحديث بطريقة واضحة ومؤثرة.","meta":{"indicator":"الذكاءات","dimension":"الذكاء اللغوي"}},{"id":113,"mode":"scale","text":"عندما ألاحظ أنني تأخرت في إنجاز مهمة عن خطتي، أعيد ترتيب وقتي أو أولوياتي حتى أستطيع إنهاءها في موعدها.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثالثة: التخطيط والتنظيم"}},{"id":114,"mode":"scale","text":"عندما تتعدد التفسيرات لنتيجة واحدة، أقارن الأدلة وأستبعد التفسيرات التي لا تتفق معها حتى أصل إلى التفسير الأكثر منطقية.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الأولى: المبادرة"}},{"id":115,"mode":"scale","text":"عندما أتعهد أمام معلم أو زملاء بإنجاز مهمة معينة، أتابعها حتى تكتمل ولا أعتمد على أن يتولى شخص آخر ما التزمت به.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثانية: تحمل المسؤولية"}},{"id":116,"mode":"scale","text":"أستطيع تخيّل الأشكال من زوايا مختلفة ومعرفة كيفية تجميع أجزائها؛ مثل تركيب جهاز أو مجسّم بالاستعانة بالرسم التوضيحي.","meta":{"indicator":"الذكاءات","dimension":"الذكاء البصري"}},{"id":117,"mode":"scale","text":"إذا واجهت موضوعًا أو مهارة جديدة، أبحث عن الطريقة والمصادر التي تساعدني على تعلمها بنفسي قبل الاعتماد الكامل على مساعدة الآخرين.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثانية: التعلم والتطوير"}},{"id":118,"mode":"scale","text":"أستطيع استخدام يدي بمهارة لإنجاز المهام العملية؛ مثل تركيب جهاز، أو إصلاح عطل بسيط، أو صنع نموذج.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الحركي"}},{"id":119,"mode":"scale","text":"عندما لا تنجح محاولتي الأولى في حل مشكلة، أراجع ما حدث وأجرب طريقة مختلفة بدلًا من تكرار الأسلوب نفسه دون تغيير.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الحادية عشرة: إدارة التغيير"}},{"id":120,"mode":"scale","text":"أستطيع تكوين علاقات مع أشخاص تختلف أعمارهم وشخصياتهم واهتماماتهم، وأكيّف طريقة تواصلي بما يناسب كل شخص.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الاجتماعي"}},{"id":121,"mode":"scale","text":"إذا لم أفهم المطلوب في مهمة أو تعليمات، أطلب التوضيح في الوقت المناسب بدلًا من الاستمرار وأنا غير متأكد مما يجب فعله.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الخامسة: التواصل الفعّال"}},{"id":122,"mode":"scale","text":"أحدد أهدافي الشخصية بناءً على معرفتي بذاتي، وما أملكه من قدرات، وما يتوافق مع اهتماماتي وطموحاتي.","meta":{"indicator":"الذكاءات","dimension":"الذكاء الذاتي"}},{"id":123,"mode":"scale","text":"أستطيع متابعة شرح شفهي يتضمن عدة أفكار، واستخلاص النقاط الرئيسة والعلاقات بينها دون الحاجة إلى عرضها مكتوبة.","meta":{"indicator":"الذكاءات","dimension":"الذكاء السمعي"}},{"id":124,"mode":"scale","text":"عندما نناقش قرارًا داخل الفريق، أشارك برأيي وأتقبل العمل برأي آخر إذا تبين أنه الأنسب لهدف الفريق.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثامنة: العمل الجماعي"}},{"id":125,"mode":"scale","text":"عندما أواجه ضغطًا أو عدة متطلبات في وقت واحد، أحافظ على قدرتي على العمل وأعيد تنظيم أسلوبي بما يتناسب مع الظروف بدلًا من أن يعطلني الضغط.","meta":{"indicator":"الكفاءات","dimension":"الكفاءة الثالثة عشرة: إدارة الضغوط"}}]};
